// Anachro Prod — Cloudflare Worker + D1
// Sert l'app (/), l'admin (/admin) et l'API (/api/*). Données dans D1 (binding DB).
// APP_HTML, ADMIN_HTML et SEED sont injectés par build.py.

const APP_HTML = "<!doctype html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"robots\" content=\"noindex\"><title>Anachro Prod</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,800&family=IBM+Plex+Sans:wght@400;500;600&family=JetBrains+Mono:wght@500;700&display=swap\">\n<style>\n/* Layout : en-tête (semaine en cours + jalon) → avancement par personne → onglets → une vue à la fois. Une couleur par personne. */\n:root{\n  --bg:#F2F3F6; --surface:#FFFFFF; --sunk:#E7E9EF; --fg:#151821; --muted:#5D6375; --line:#D3D7E0;\n  --accent:#C2410C; --accent-soft:#FBE3D6;\n  --theo:#2F5FD0; --theo-soft:#E2EAFB; --celian:#1F8A5B; --celian-soft:#DDF3E8; --olivier:#B4590E; --olivier-soft:#FBE9D8;\n  --art:#8B3FB8; --art-soft:#F1E3F8; --tous:#4B5263; --tous-soft:#E4E6EC;\n  --doing:#B7860B; --doing-soft:#FBF0CF; --done:#1F8A5B; --done-soft:#DDF3E8; --blocked:#C0262D; --blocked-soft:#FBDADB;\n  --scrim:rgba(15,18,26,.45);\n  --f-display:\"Bricolage Grotesque\",ui-sans-serif,system-ui,sans-serif;\n  --f-body:\"IBM Plex Sans\",ui-sans-serif,system-ui,sans-serif;\n  --f-mono:\"JetBrains Mono\",ui-monospace,SFMono-Regular,Menlo,monospace;\n  --r:10px;\n}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){\n  --bg:#12141A; --surface:#1B1E26; --sunk:#242833; --fg:#E9EBF1; --muted:#9BA1B3; --line:#323746;\n  --accent:#F08A4B; --accent-soft:#3A2418;\n  --theo:#7FA3F5; --theo-soft:#1D2742; --celian:#5CC994; --celian-soft:#16301F; --olivier:#F0A061; --olivier-soft:#3A2614;\n  --art:#C990EC; --art-soft:#2E1F3A; --tous:#AEB4C4; --tous-soft:#262A35;\n  --doing:#E9BC45; --doing-soft:#3A3014; --done:#5CC994; --done-soft:#16301F; --blocked:#F0686E; --blocked-soft:#3D1A1C;\n  --scrim:rgba(0,0,0,.6); color-scheme:dark}}\n:root[data-theme=\"dark\"]{\n  --bg:#12141A; --surface:#1B1E26; --sunk:#242833; --fg:#E9EBF1; --muted:#9BA1B3; --line:#323746;\n  --accent:#F08A4B; --accent-soft:#3A2418;\n  --theo:#7FA3F5; --theo-soft:#1D2742; --celian:#5CC994; --celian-soft:#16301F; --olivier:#F0A061; --olivier-soft:#3A2614;\n  --art:#C990EC; --art-soft:#2E1F3A; --tous:#AEB4C4; --tous-soft:#262A35;\n  --doing:#E9BC45; --doing-soft:#3A3014; --done:#5CC994; --done-soft:#16301F; --blocked:#F0686E; --blocked-soft:#3D1A1C;\n  --scrim:rgba(0,0,0,.6); color-scheme:dark}\n*{box-sizing:border-box}\nbody{background:var(--bg);color:var(--fg);font-family:var(--f-body);font-size:16px;line-height:1.5}\n.wrap{max-width:1320px;margin:0 auto;padding-inline:20px;padding-block:24px 64px}\nh1,h2,h3{font-family:var(--f-display);margin:0;text-wrap:balance;letter-spacing:-.01em}\nbutton{font-family:inherit}\n.muted{color:var(--muted)}\n\n.top{display:grid;grid-template-columns:1fr auto;gap:16px 24px;align-items:end;margin-bottom:20px}\n.top h1{font-size:clamp(30px,5vw,44px);font-weight:800}\n.top .sub{color:var(--muted);margin-top:2px}\n.now{display:flex;gap:12px;flex-wrap:wrap}\n.pill-box{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:10px 14px;min-width:0}\n.pill-box .k{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);font-weight:600}\n.pill-box .v{font-family:var(--f-display);font-size:20px;font-weight:600;line-height:1.2}\n.pill-box .v small{font-family:var(--f-body);font-size:14px;color:var(--muted);font-weight:500}\n.pill-box.hot{border-color:var(--accent);background:var(--accent-soft)}\n\n.progress{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-bottom:18px}\n.prog{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:10px 12px;min-width:0}\n.prog .row{display:flex;justify-content:space-between;align-items:baseline;gap:8px}\n.prog .name{font-weight:600;font-size:16px;display:flex;align-items:center;gap:8px;min-width:0}\n.prog .pct{font-family:var(--f-mono);font-weight:700;font-variant-numeric:tabular-nums}\n.bar{height:8px;background:var(--sunk);border-radius:99px;overflow:hidden;margin-top:8px;display:flex}\n.bar i{display:block;height:100%}\n.prog .meta{font-size:13px;color:var(--muted);margin-top:6px;font-variant-numeric:tabular-nums}\n.dot{width:10px;height:10px;border-radius:50%;display:inline-block;flex:none}\n\n.tabs{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:var(--bg);display:flex;gap:6px;overflow-x:auto;padding-block:8px;margin-bottom:16px;border-bottom:1px solid var(--line)}\n.tabs button{font:600 15px var(--f-body);color:var(--muted);background:none;border:0;padding:9px 14px;border-radius:8px;cursor:pointer;white-space:nowrap}\n.tabs button:hover{background:var(--sunk);color:var(--fg)}\n.tabs button[aria-selected=\"true\"]{background:var(--fg);color:var(--bg)}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n\n.note{font-size:14px;color:var(--muted);margin:0 0 14px}\n.banner{background:var(--doing-soft);border:1px solid var(--doing);border-radius:var(--r);padding:10px 14px;font-size:14px;margin-bottom:16px}\n.empty{padding:18px;color:var(--muted);font-size:15px;background:var(--surface);border:1px dashed var(--line);border-radius:var(--r)}\n\n/* Cette semaine */\n.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px;align-items:start}\n.col{min-width:0;display:flex;flex-direction:column;gap:10px}\n.colh{display:flex;align-items:center;gap:10px;padding:4px 2px;border-bottom:3px solid var(--c);}\n.colh h3{font-size:21px}\n.colh span{font-size:13px;color:var(--muted);margin-left:auto}\n\n.gcard{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;min-width:0}\n.gcard>header{display:flex;gap:8px;align-items:baseline;padding:10px 12px 6px;flex-wrap:wrap}\n.gcard>header h4{margin:0;font-size:16px;font-weight:600}\n.gcard>header .cnt{margin-left:auto;font-family:var(--f-mono);font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums}\n.tag{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;padding:2px 6px;border-radius:5px;background:var(--c-soft);color:var(--c)}\n.gcard.alldone>header h4{text-decoration:line-through;color:var(--muted)}\n.subs{display:flex;flex-direction:column;padding:0 4px 6px}\n.sub{display:flex;gap:10px;align-items:flex-start;padding:6px 8px;border-radius:7px}\n.sub:hover{background:var(--sunk)}\n.sub input[type=checkbox]{width:18px;height:18px;margin:2px 0 0;accent-color:var(--done);flex:none;cursor:pointer}\n.sub .txt{flex:1;min-width:0;font-size:15px;line-height:1.4}\n.sub.done .txt{text-decoration:line-through;color:var(--muted)}\n.sub .who{font-size:12px;color:var(--muted);display:block}\n.badge{display:inline-block;font-size:11px;font-weight:700;padding:1px 6px;border-radius:5px;margin-left:6px;vertical-align:1px}\n.badge.doing{background:var(--doing-soft);color:var(--doing)}\n.badge.blocked{background:var(--blocked-soft);color:var(--blocked)}\n.edit{flex:none;border:0;background:none;color:var(--muted);cursor:pointer;font-size:15px;padding:0 4px;border-radius:5px;opacity:.55}\n.sub:hover .edit,.edit:focus-visible{opacity:1}\n.late{margin-top:4px}\n.late>summary{cursor:pointer;font-weight:600;color:var(--blocked);font-size:14px;padding:4px 2px}\n\n/* Planning */\n.plan{overflow-x:auto}\n.pgrid{display:grid;grid-template-columns:120px repeat(5,minmax(170px,1fr));min-width:1000px}\n.pgrid>div{padding:10px 8px;border-bottom:1px solid var(--line);min-width:0}\n.phead{position:sticky;top:0;background:var(--bg);font-weight:700;border-bottom:2px solid var(--fg)!important;display:flex;gap:6px;align-items:center}\n.wk h3{font-size:22px;font-weight:800}\n.wk .d{font-size:13px;color:var(--muted)}\n.wk.cur h3{color:var(--accent)}\n.row-past{opacity:.5}\n.mile{display:inline-block;margin-top:4px;font-size:12px;font-weight:700;padding:2px 7px;border-radius:6px;background:var(--accent-soft);color:var(--accent)}\n.now-tag{display:inline-block;margin-top:4px;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:2px 7px;border-radius:6px;background:var(--accent);color:var(--bg)}\n.chips{display:flex;flex-direction:column;gap:5px}\n.chip{display:flex;gap:6px;justify-content:space-between;align-items:baseline;padding:6px 8px;border-radius:7px;font-size:13.5px;line-height:1.3;background:var(--c-soft);color:var(--fg);border:1px solid transparent}\n.chip b{font-family:var(--f-mono);font-size:11.5px;color:var(--c);flex:none;font-variant-numeric:tabular-nums}\n.chip.cdone{opacity:.55;text-decoration:line-through}\n.chip.cblocked{border-color:var(--blocked)}\n.gapline{grid-column:1/-1;padding:9px 8px!important;font-size:13.5px;color:var(--muted);background:repeating-linear-gradient(135deg,transparent 0 8px,var(--sunk) 8px 9px)}\n.phase{grid-column:1/-1;font-size:12px;text-transform:uppercase;letter-spacing:.1em;font-weight:700;color:var(--accent);padding-top:22px!important}\n\n/* Toutes les tâches */\n.toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:14px}\n.chipbtn{font:600 14px var(--f-body);border:1.5px solid var(--line);background:var(--surface);color:var(--fg);padding:6px 12px;border-radius:99px;cursor:pointer;display:flex;gap:6px;align-items:center}\n.chipbtn[aria-pressed=\"true\"]{border-color:var(--fg);background:var(--fg);color:var(--bg)}\n.toolbar select,.toolbar input,.form select,.form input{font:500 14px var(--f-body);padding:7px 10px;border:1.5px solid var(--line);border-radius:8px;background:var(--surface);color:var(--fg);min-width:0}\n.toolbar input[type=search]{flex:1 1 200px}\n.primary{font:600 14px var(--f-body);background:var(--accent);color:#fff;border:0;border-radius:8px;padding:8px 14px;cursor:pointer}\n.ghost{font:600 14px var(--f-body);background:none;color:var(--fg);border:1.5px solid var(--line);border-radius:8px;padding:8px 14px;cursor:pointer}\n.danger{font:600 14px var(--f-body);background:none;color:var(--blocked);border:1.5px solid var(--blocked);border-radius:8px;padding:8px 14px;cursor:pointer}\n.wgroup{margin-bottom:22px}\n.wgroup>h3{font-size:19px;margin-bottom:8px;display:flex;gap:10px;align-items:baseline;flex-wrap:wrap}\n.wgroup>h3 small{font:500 14px var(--f-body);color:var(--muted)}\n.ggrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:10px;align-items:start}\n\n/* Jalons / infos */\n.miles{display:flex;flex-direction:column;gap:10px}\n.ms{display:grid;grid-template-columns:110px minmax(0,1fr) auto;gap:16px;align-items:center;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px}\n.ms .when{font-family:var(--f-display);font-weight:800;font-size:22px;line-height:1.1}\n.ms .when small{display:block;font:500 14px var(--f-body);color:var(--muted)}\n.ms h3{font-size:19px}\n.ms p{margin:2px 0 0;color:var(--muted);font-size:15px}\n.ms .state{font-size:13px;font-weight:700;padding:4px 10px;border-radius:99px;white-space:nowrap}\n.ms.next{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}\n.st-past{background:var(--sunk);color:var(--muted)} .st-next{background:var(--accent);color:var(--bg)} .st-later{background:var(--sunk);color:var(--fg)}\n.alerts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:28px}\n.alert{background:var(--surface);border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:var(--r);padding:14px 16px;min-width:0}\n.alert h3{font-size:18px;margin-bottom:4px}\n.alert p{margin:0;color:var(--muted);font-size:15px}\n.roles{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-bottom:24px}\n.role{border-radius:var(--r);padding:14px 16px;min-width:0;background:var(--c-soft)}\n.role h3{font-size:21px;color:var(--c)}\n.role p{margin:4px 0 0;font-size:15px}\n.rename{display:flex;gap:10px;flex-wrap:wrap;align-items:end}\n.rename label{display:flex;flex-direction:column;gap:4px;font-size:13px;font-weight:600;color:var(--muted)}\n\n/* Règles */\ndetails.rule{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);margin-bottom:10px;overflow:hidden}\ndetails.rule>summary{cursor:pointer;padding:14px 16px;font-family:var(--f-display);font-weight:600;font-size:20px;list-style:none;display:flex;justify-content:space-between;gap:12px}\ndetails.rule>summary::-webkit-details-marker{display:none}\ndetails.rule>summary::after{content:\"+\";font-family:var(--f-mono);color:var(--muted)}\ndetails.rule[open]>summary::after{content:\"–\"}\n.rb{padding:0 16px 16px}\n.rb ol,.rb ul{margin:0;padding-left:22px}\n.rb li{margin:6px 0}\n.rb li b{font-weight:600}\n.rb li span{color:var(--muted)}\npre.tree{font-family:var(--f-mono);font-size:13.5px;background:var(--sunk);border-radius:8px;padding:14px;overflow-x:auto;margin:0 0 10px;line-height:1.55}\n.tbl{overflow-x:auto}\ntable{border-collapse:collapse;width:100%;font-size:15px}\nth,td{text-align:left;padding:9px 10px;border-bottom:1px solid var(--line);vertical-align:top}\nth{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}\ntd code,li code,p code{font-family:var(--f-mono);font-size:13px;background:var(--sunk);padding:1px 5px;border-radius:4px}\n\n/* Éditeur */\n.scrim{position:fixed;inset:0;background:var(--scrim);z-index:20;display:flex;align-items:flex-start;justify-content:center;padding:max(40px,env(safe-area-inset-top,0px)) 16px 16px;overflow-y:auto}\n.form{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:20px;width:min(560px,100%);display:flex;flex-direction:column;gap:12px}\n.form h2{font-size:22px}\n.form label{display:flex;flex-direction:column;gap:4px;font-size:13px;font-weight:600;color:var(--muted)}\n.form .two{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.form .actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:4px}\n.form .actions .sp{flex:1}\n.form .err{color:var(--blocked);font-size:14px;margin:0}\n\n.c-theo{--c:var(--theo);--c-soft:var(--theo-soft)} .c-celian{--c:var(--celian);--c-soft:var(--celian-soft)} .c-olivier{--c:var(--olivier);--c-soft:var(--olivier-soft)}\n.c-art{--c:var(--art);--c-soft:var(--art-soft)} .c-tous{--c:var(--tous);--c-soft:var(--tous-soft)}\n\n\n/* Liens rapides (GDD…) */\n.quick{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}\n.qbtn{display:inline-flex;align-items:center;gap:7px;font:600 14px var(--f-body);text-decoration:none;color:var(--fg);background:var(--surface);border:1.5px solid var(--line);border-radius:99px;padding:6px 14px}\n.qbtn:hover{border-color:var(--fg)}\n.qbtn.main{background:var(--fg);color:var(--bg);border-color:var(--fg)}\n.qbtn .ext{font-size:12px;opacity:.7}\n.qbtn.add{border-style:dashed;color:var(--muted)}\na{color:var(--accent)}\n.linkbtn{font:inherit;color:var(--accent);background:none;border:0;padding:0;cursor:pointer;text-decoration:underline;text-underline-offset:2px}\n.pill-box.clk{cursor:pointer;text-align:left;font:inherit;color:inherit}\n.pill-box.clk:hover{box-shadow:0 0 0 2px var(--accent)}\n\n/* Groupes repliables */\n.gcard>header{cursor:pointer;user-select:none}\n.gcard>header::after{content:\"▾\";font-size:12px;color:var(--muted);margin-left:2px;transition:transform .15s}\n.gcard.shut>header::after{transform:rotate(-90deg)}\n.gcard.shut>.subs{display:none}\n.gcard.hl{box-shadow:0 0 0 3px var(--accent)}\n\n/* Toutes les tâches : liste compacte */\n.spr{margin-bottom:18px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden}\n.spr.cur{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}\n.sprh{all:unset;box-sizing:border-box;cursor:pointer;width:100%;display:grid;grid-template-columns:auto minmax(0,1fr) minmax(90px,180px) auto;gap:14px;align-items:center;padding:12px 16px;background:var(--sunk)}\n.sprh:hover{background:var(--line)}\n.sprh:focus-visible{outline:3px solid var(--accent);outline-offset:-3px}\n.sprh .sn{font-family:var(--f-display);font-weight:800;font-size:24px;line-height:1}\n.sprh .sd{font-size:14px;color:var(--muted);min-width:0}\n.sprh .sd b{color:var(--fg);font-weight:600}\n.sprh .sm{display:inline-block;font-size:12px;font-weight:700;padding:2px 7px;border-radius:6px;background:var(--accent-soft);color:var(--accent);margin-left:6px}\n.sprh .go{font-size:13px;font-weight:600;color:var(--accent);white-space:nowrap}\n.mbar{height:6px;background:var(--line);border-radius:99px;overflow:hidden;display:flex}\n.mbar i{display:block;height:100%}\n.mnum{font-family:var(--f-mono);font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums;margin-top:3px;text-align:right}\n.glist{display:flex;flex-direction:column}\n.grow{border-top:1px solid var(--line)}\n.grow>button{all:unset;box-sizing:border-box;cursor:pointer;width:100%;display:grid;grid-template-columns:4px minmax(0,1fr) auto 110px 16px;gap:12px;align-items:center;padding:9px 16px 9px 0}\n.grow>button:hover{background:var(--sunk)}\n.grow>button:focus-visible{outline:3px solid var(--accent);outline-offset:-3px}\n.grow .stripe{align-self:stretch;background:var(--c);border-radius:0 3px 3px 0}\n.grow .gt{font-weight:600;font-size:15px;min-width:0;display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.grow .gw{font-size:13px;color:var(--muted);white-space:nowrap}\n.grow .chev{font-size:12px;color:var(--muted);transition:transform .15s}\n.grow.open .chev{transform:rotate(90deg)}\n.grow.alldone .gt>span:first-child{text-decoration:line-through;color:var(--muted)}\n.grow .subs{padding:0 12px 10px 20px}\n.grow .badge{margin-left:0}\n.mini{display:flex;flex-direction:column;gap:3px}\n\n/* Fenêtre sprint */\n.sheet{background:var(--bg);border:1px solid var(--line);border-radius:14px;width:min(1100px,100%);display:flex;flex-direction:column;overflow:hidden;margin-bottom:24px}\n.sheet>header{background:var(--surface);border-bottom:1px solid var(--line);padding:18px 20px;display:flex;flex-direction:column;gap:12px}\n.sheet .sh1{display:flex;gap:12px;align-items:flex-start;flex-wrap:wrap}\n.sheet .sh1 h2{font-size:30px;font-weight:800;line-height:1.1}\n.sheet .sh1 h2 small{font:500 16px var(--f-body);color:var(--muted);margin-left:8px}\n.sheet .sh1 .sp{flex:1}\n.sheet .navb{display:flex;gap:6px}\n.sheet .st{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;padding:3px 9px;border-radius:99px;background:var(--sunk);color:var(--muted)}\n.sheet .st.live{background:var(--accent);color:var(--bg)}\n.sheet .milebox{background:var(--accent-soft);border-radius:var(--r);padding:10px 14px;font-size:15px}\n.sheet .milebox b{color:var(--accent)}\n.sheet .stats{display:flex;gap:18px;flex-wrap:wrap;align-items:center;font-size:14px;color:var(--muted)}\n.sheet .stats .bar{flex:1 1 220px;margin:0;height:10px}\n.sheet .stats b{color:var(--fg);font-variant-numeric:tabular-nums}\n.sheet .sb{padding:18px 20px;display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;align-items:start}\n.sheet .sb .col{gap:8px}\n@media (max-width:700px){\n  .sprh{grid-template-columns:auto minmax(0,1fr)}\n  .sprh .mini,.sprh .go{grid-column:2}\n  .grow>button{grid-template-columns:4px minmax(0,1fr) 16px}\n  .grow .gw,.grow .mini{display:none}\n  .sheet .sh1 h2{font-size:24px}\n  .scrim{padding:8px}\n}\nbutton.chip{font:inherit;font-size:13.5px;width:100%;text-align:left;cursor:pointer}\nbutton.chip:hover{border-color:var(--c)}\n.wk button{all:unset;cursor:pointer;display:block}\n.wk button:hover h3{color:var(--accent)}\n.wk button:focus-visible{outline:3px solid var(--accent);outline-offset:2px;border-radius:6px}\n.wk .see{font-size:12px;font-weight:600;color:var(--accent)}\n.ms.clk{cursor:pointer}\n.ms.clk:hover{border-color:var(--fg)}\n@media (max-width:1000px){.progress{grid-template-columns:repeat(3,minmax(0,1fr))}}\n@media (max-width:700px){\n  .progress,.alerts{grid-template-columns:1fr}\n  .top{grid-template-columns:1fr}\n  .ms{grid-template-columns:1fr}\n  .form .two{grid-template-columns:1fr}\n}\n@media (prefers-reduced-motion:no-preference){.tabs button,.chipbtn,.sub{transition:background .15s,color .15s,border-color .15s}}\n</style></head><body>\n\n<div class=\"wrap\">\n  <div class=\"top\">\n    <div>\n      <h1>Anachro — Prod</h1>\n      <div class=\"sub\">Théo · Célian · Olivier · les artistes — sortie Steam fin mars 2027, MAJ en avril et juin</div>\n      <div class=\"quick\" id=\"quick\"></div>\n    </div>\n    <div class=\"now\" id=\"now\"></div>\n  </div>\n\n  <div class=\"progress\" id=\"progress\"></div>\n\n  <nav class=\"tabs\" role=\"tablist\" aria-label=\"Sections\">\n    <button role=\"tab\" data-tab=\"semaine\" id=\"tab-semaine\">Cette semaine</button>\n    <button role=\"tab\" data-tab=\"planning\" id=\"tab-planning\">Planning</button>\n    <button role=\"tab\" data-tab=\"taches\" id=\"tab-taches\">Toutes les tâches</button>\n    <button role=\"tab\" data-tab=\"jalons\" id=\"tab-jalons\">Jalons</button>\n    <button role=\"tab\" data-tab=\"infos\" id=\"tab-infos\">Infos &amp; alertes</button>\n    <button role=\"tab\" data-tab=\"regles\" id=\"tab-regles\">Code &amp; règles</button>\n  </nav>\n\n  <div id=\"dbnote\" class=\"banner\" hidden></div>\n\n  <section data-panel=\"semaine\" id=\"p-semaine\"><div class=\"empty\">Chargement des tâches…</div></section>\n  <section data-panel=\"planning\" id=\"p-planning\" hidden></section>\n  <section data-panel=\"taches\" id=\"p-taches\" hidden></section>\n  <section data-panel=\"jalons\" id=\"p-jalons\" hidden></section>\n  <section data-panel=\"infos\" id=\"p-infos\" hidden></section>\n  <section data-panel=\"regles\" id=\"p-regles\" hidden>\n    <details class=\"rule\" open>\n      <summary>Arborescence du projet</summary>\n      <div class=\"rb\">\n<pre class=\"tree\">Assets/\n├── _Project/\n│   ├── Art/        Models/ Materials/ Textures/ Animations/ VFX/     → artistes\n│   ├── Audio/      Music/ Sfx/ Mixers/                               → Olivier\n│   ├── Data/       ScriptableObjects : Anachronisms/ Eras/ MatchPresets/ → Célian\n│   ├── Prefabs/    Network/ Player/ Npc/ Anachronisms/ Props/ UI/\n│   ├── Scenes/     Boot, MainMenu, Maps/Map_&lt;Epoque&gt;, Sandbox/Sandbox_&lt;Prenom&gt;\n│   └── Scripts/\n│       ├── Core/       bootstrap, utilitaires                      → tous\n│       ├── Network/    MatchManager, lobby Steam, observers, vocal → Théo\n│       ├── Gameplay/   Player/ Weapon/ Placement/ Portal/ Photos/  → Célian\n│       ├── Npc/        IA, spawner de foule                        → Olivier\n│       ├── World/      Degradation/ Glitch/                        → Olivier\n│       ├── UI/         Hud/ Menus/ Lobby/                          → Olivier\n│       └── Editor/     outils éditeur\n└── ThirdParty/         FishNet, FishySteamworks (ne jamais modifier)</pre>\n        <ul>\n          <li><b>Namespace = dossier</b> : <code>Anachronism.Network</code>, <code>Anachronism.Gameplay</code>, <code>Anachronism.Npc</code>…</li>\n          <li><b>2 asmdefs seulement</b> : <code>Anachronism.Runtime</code> et <code>Anachronism.Editor</code>. On découpe si la compil devient lente.</li>\n          <li><b>Un dossier = un responsable.</b> Pour toucher le dossier d'un autre, on le prévient.</li>\n        </ul>\n      </div>\n    </details>\n    <details class=\"rule\">\n      <summary>Conventions de nommage</summary>\n      <div class=\"rb tbl\">\n        <table>\n          <thead><tr><th>Quoi</th><th>Convention</th><th>Exemple</th></tr></thead>\n          <tbody>\n            <tr><td>Classe, méthode, propriété, event, enum</td><td>PascalCase</td><td><code>MatchManager</code>, <code>StartMatch()</code></td></tr>\n            <tr><td>Champ privé (y compris <code>[SerializeField]</code>)</td><td>_camelCase</td><td><code>[SerializeField] private float _shootCooldown;</code></td></tr>\n            <tr><td>Paramètre, variable locale</td><td>camelCase</td><td><code>claimedTarget</code></td></tr>\n            <tr><td>Constante, static readonly</td><td>PascalCase</td><td><code>MaxPlayers</code></td></tr>\n            <tr><td>Interface</td><td>I + PascalCase</td><td><code>IShootable</code></td></tr>\n            <tr><td>Booléen</td><td>Is / Has / Can</td><td><code>IsFound</code>, <code>_hasPlaced</code></td></tr>\n            <tr><td>Event / handler</td><td>passé / On…</td><td><code>VillainCaptured</code> / <code>OnVillainCaptured</code></td></tr>\n            <tr><td>RPC FishNet</td><td>suffixe du type</td><td><code>ShootServerRpc</code>, <code>PlayFxObserversRpc</code>, <code>TargetAssignRole</code></td></tr>\n            <tr><td>Fichier</td><td>1 classe publique = 1 fichier</td><td><code>MatchManager.cs</code></td></tr>\n            <tr><td>Prefab</td><td>préfixe de domaine</td><td><code>Npc_Villager</code>, <code>Anachro_Phone</code></td></tr>\n            <tr><td>Scène</td><td>Map_ / Sandbox_</td><td><code>Map_Rome</code>, <code>Sandbox_Celian</code></td></tr>\n            <tr><td>Assets art</td><td>SM_ SK_ M_ T_ A_</td><td><code>SM_Phone</code>, <code>T_Phone_Albedo</code></td></tr>\n          </tbody>\n        </table>\n        <p class=\"note\" style=\"margin-top:10px\">Toujours écrire <code>private</code> / <code>public</code>. Jamais de champ public : <code>[SerializeField] private</code> + propriété.</p>\n      </div>\n    </details>\n    <details class=\"rule\">\n      <summary>Règles de code</summary>\n      <div class=\"rb\"><ol>\n        <li><b>Pas de Find / FindObjectOfType / GetComponent dans Update.</b> <span>Références via l'inspecteur ou cache dans Awake.</span></li>\n        <li><b>Singletons : seulement MatchManager et les services de Core.</b> <span>Pas de nouveau sans en parler.</span></li>\n        <li><b>Valeurs d'équilibrage dans des ScriptableObjects.</b> <span>Rien en dur dans le code.</span></li>\n        <li><b>Events C# pour découpler.</b> <span>Monde, UI, audio écoutent MatchManager, ne le modifient jamais.</span></li>\n        <li><b>L'UI ne touche jamais le réseau.</b> <span>UI → gameplay → RPC.</span></li>\n        <li><b>Règles partagées client/serveur = fonctions pures.</b> <span>Ex : validité d'une pose, utilisée par l'aperçu et par le serveur.</span></li>\n        <li><b>Commentaires = le pourquoi.</b> <span><code>// TODO (Prénom) :</code> pour ce qui reste.</span></li>\n      </ol></div>\n    </details>\n    <details class=\"rule\">\n      <summary>Règles réseau (FishNet, l'hôte = serveur)</summary>\n      <div class=\"rb\"><ol>\n        <li><b>L'hôte décide de tout</b> : phases, rôles, pose, tirs, munitions, capture, victoire. <span>Le client envoie des intentions, jamais des résultats.</span></li>\n        <li><b>Toute RPC client → serveur est hostile.</b> <span>Vérifier rôle, phase, cadence, distance, état.</span></li>\n        <li><b>Aucun secret en SyncVar.</b> <span>Le rôle passe par TargetRpc, « est un anachronisme » reste sur le serveur.</span></li>\n        <li><b>SyncVar = état, RPC = événement.</b> <span>Animations et FX calculés en local.</span></li>\n        <li><b>PNJ et méchant : synchro strictement identique.</b> <span>Même NetworkTransform, même fréquence, Animator par la vitesse. Sinon le méchant se repère.</span></li>\n        <li><b>Le temps en ticks</b> (TimeManager), <span>pas Time.time côté client.</span></li>\n        <li><b>Code des deux côtés protégé</b> par IsServerInitialized / IsOwner, <span>méthodes serveur en [Server].</span></li>\n        <li><b>Tester avec hôte + 2 clients</b>, <span>et chaque semaine à 120 ms / 2 % de perte.</span></li>\n        <li><b>Seul point client-autoritaire : le mouvement.</b> <span>Pas de prédiction / réconciliation.</span></li>\n        <li><b>Vocal de proximité pour tous, sans indicateur au-dessus des têtes.</b> <span>Sinon le méchant qui parle est repéré.</span></li>\n      </ol></div>\n    </details>\n    <details class=\"rule\">\n      <summary>Git</summary>\n      <div class=\"rb\"><ul>\n        <li><b>Setup :</b> <span>.gitignore Unity officiel, Force Text, Visible Meta Files, Git LFS (fbx, blend, png, psd, tga, wav, ogg, mp3, ttf), .gitattributes avec unityyamlmerge.</span></li>\n        <li><b>Branches :</b> <span><code>main</code> toujours buildable · <code>develop</code> intégration · <code>feature/prenom-sujet</code> · <code>fix/sujet</code>.</span></li>\n        <li><b>PR :</b> <span>petites, relues par un autre dev.</span></li>\n        <li><b>Commits :</b> <span><code>feat: pose des objets</code> · <code>fix: désync PNJ</code> · <code>ld: greybox marché</code>.</span></li>\n        <li><b>Scènes :</b> <span>chacun dans <code>Sandbox_Prenom</code>. La map = Théo, les autres ajoutent des prefabs. <code>git lfs lock</code> avant de toucher une scène partagée.</span></li>\n        <li><b>.meta :</b> <span>toujours committés. Jamais renommer / déplacer un asset hors de Unity.</span></li>\n        <li><b>Références Missing :</b> <span>.meta manquant. Images de 130 octets : <code>git lfs install &amp;&amp; git lfs pull</code>.</span></li>\n      </ul></div>\n    </details>\n    <details class=\"rule\">\n      <summary>Code déjà fourni (zip)</summary>\n      <div class=\"rb tbl\">\n        <table>\n          <thead><tr><th>Fichier</th><th>Contenu</th><th>Suite</th></tr></thead>\n          <tbody>\n            <tr><td><code>Network/GameTypes.cs</code></td><td>Phases, rôles, vainqueur, réglages + préréglages</td><td>Théo</td></tr>\n            <tr><td><code>Network/MatchManager.cs</code></td><td>Phases, rôles secrets, chrono, dégradation, munitions, tir validé serveur, capture, portail</td><td>Théo</td></tr>\n            <tr><td><code>Network/HiddenWhileHidingCondition.cs</code></td><td>Méchants + objets invisibles aux gentils pendant la cache</td><td>Théo</td></tr>\n            <tr><td><code>Gameplay/Anachronisms/PlacedAnachronism.cs</code></td><td>Objet posé, état « trouvé »</td><td>Célian</td></tr>\n            <tr><td><code>Npc/NpcAgent.cs</code></td><td>Marqueur PNJ, IA à écrire</td><td>Olivier</td></tr>\n          </tbody>\n        </table>\n        <p class=\"note\" style=\"margin-top:10px\">Écrit pour FishNet v4, non compilé : vérifier les signatures à l'import.</p>\n      </div>\n    </details>\n  </section>\n</div>\n<div id=\"sprint\" hidden></div>\n<div id=\"editor\" hidden></div>\n\n<script>\nconst ST = {todo:\"À faire\", doing:\"En cours\", done:\"Fait\", blocked:\"Bloqué\"};\nconst PEOPLE = {theo:\"Théo\", celian:\"Célian\", olivier:\"Olivier\", art1:\"Hugo\", art2:\"JB\", tous:\"Équipe\"};\nconst COLS = [\n  {k:\"theo\", who:[\"theo\"]}, {k:\"celian\", who:[\"celian\"]}, {k:\"olivier\", who:[\"olivier\"]},\n  {k:\"art\", label:\"Artistes\", who:[\"art1\",\"art2\"]}, {k:\"tous\", label:\"Équipe (hors code)\", who:[\"tous\"]},\n];\nconst CATS = [\"Online\",\"LD\",\"Gameplay\",\"Data\",\"PNJ\",\"Monde\",\"UI\",\"Audio\",\"Outils\",\"Art\",\"Prod\",\"Playtest\",\"Steam\",\"Marketing\"];\nconst colorOf = who => who && who.startsWith(\"art\") ? \"art\" : (who || \"tous\");\nconst colLabel = c => c.label || PEOPLE[c.k];\n\nconst WEEKS = [\n  {s:\"S1\", d:\"5–9 oct\", a:\"2026-10-05\", b:\"2026-10-09\"},\n  {s:\"S2\", d:\"12–16 oct\", a:\"2026-10-12\", b:\"2026-10-16\", phase:\"Bloc 1 — fondations\"},\n  {s:\"S3\", d:\"19–23 oct\", a:\"2026-10-19\", b:\"2026-10-23\", m:\"Boucle en LAN\"},\n  {gap:\"26 oct → 27 nov · pas de studio (cours + Quête I1)\"},\n  {s:\"S4\", d:\"30 nov–4 déc\", a:\"2026-11-30\", b:\"2026-12-04\", m:\"1re partie en ligne\", phase:\"Bloc 2 — jeu complet\"},\n  {s:\"S5\", d:\"7–11 déc\", a:\"2026-12-07\", b:\"2026-12-11\"},\n  {s:\"S6\", d:\"14–18 déc\", a:\"2026-12-14\", b:\"2026-12-18\", m:\"Core gelé + page Steam\"},\n  {gap:\"Vacances + 4–8 jan · pas de studio\"},\n  {s:\"S7\", d:\"11–15 jan\", a:\"2027-01-11\", b:\"2027-01-15\", phase:\"Bloc 3 — démo\"},\n  {s:\"S8\", d:\"18–22 jan\", a:\"2027-01-18\", b:\"2027-01-22\"},\n  {s:\"S9\", d:\"25–29 jan\", a:\"2027-01-25\", b:\"2027-01-29\", m:\"Démo Next Fest\"},\n  {gap:\"1 fév → 5 mars · pas de studio (cours + Quête I2)\"},\n  {s:\"S10\", d:\"8–12 mars\", a:\"2027-03-08\", b:\"2027-03-12\", phase:\"Bloc 4 — sortie\"},\n  {s:\"S11\", d:\"15–19 mars\", a:\"2027-03-15\", b:\"2027-03-19\", m:\"Release candidate\"},\n  {s:\"S12\", d:\"22–26 mars\", a:\"2027-03-22\", b:\"2027-03-26\", m:\"SORTIE\"},\n  {gap:\"29 mars → 2 avr · pas de studio — surveiller avis et bugs\"},\n  {s:\"S13\", d:\"5–9 avr\", a:\"2027-04-05\", b:\"2027-04-09\", phase:\"Studio #2 — MAJ 1.1\"},\n  {s:\"S14\", d:\"12–16 avr\", a:\"2027-04-12\", b:\"2027-04-16\"},\n  {s:\"S15\", d:\"19–23 avr\", a:\"2027-04-19\", b:\"2027-04-23\", m:\"MAJ 1.1\"},\n  {gap:\"26 avr → 28 mai · pas de studio (cours + Quête I3)\"},\n  {s:\"S16\", d:\"31 mai–4 juin\", a:\"2027-05-31\", b:\"2027-06-04\", phase:\"Studio #2 — MAJ 1.2\"},\n  {s:\"S17\", d:\"7–11 juin\", a:\"2027-06-07\", b:\"2027-06-11\"},\n  {s:\"S18\", d:\"14–18 juin\", a:\"2027-06-14\", b:\"2027-06-18\", m:\"MAJ 1.2 + jury\"},\n];\nconst SW = WEEKS.filter(w=>w.s);\nconst MILES = [\n  [\"S3\",\"23 oct\",\"Boucle en LAN\",\"Greybox, 3 instances : rôles secrets, PNJ, cache, recherche, tir validé serveur\",\"2026-10-23\"],\n  [\"S4\",\"4 déc\",\"1re partie en ligne\",\"Via Steam sur PC différents, de bout en bout. Playtest à 4+\",\"2026-12-04\"],\n  [\"S6\",\"18 déc\",\"Core gelé\",\"Playtest à 8, vocal OK, dégradation OK. Page Steam en ligne\",\"2026-12-18\"],\n  [\"S9\",\"29 jan\",\"Démo\",\"Map 1 avec l'art, stable à 120 ms / 2 %. Envoyée au Next Fest\",\"2027-01-29\"],\n  [\"S11\",\"19 mars\",\"Release candidate\",\"Zéro bug bloquant, build en review Steam\",\"2027-03-19\"],\n  [\"S12\",\"26 mars\",\"Sortie\",\"Jeu en vente sur Steam\",\"2027-03-26\"],\n  [\"S15\",\"23 avr\",\"MAJ 1.1\",\"Bugs majeurs corrigés + 2-3 demandes des joueurs\",\"2027-04-23\"],\n  [\"S18\",\"18 juin\",\"MAJ 1.2\",\"Map 2 + nouveaux anachronismes, avant les soldes d'été Steam\",\"2027-06-18\"],\n];\nconst ALERTS = [\n  [\"Il reste 10,5 semaines de studio, pas 20\",\"Jusqu'à fin mars : S2 → S12, environ 315 h par dev. Février : 0 semaine studio, novembre : 1.\"],\n  [\"1 map en mars, la 2e en juin\",\"Sortie avec 1 map bien finie. MAJ 1.1 fin avril (bugs), MAJ 1.2 mi-juin (map 2).\"],\n  [\"Démo finie le 29 janvier\",\"Le Next Fest est en février et il n'y a aucune semaine studio en février. Vérifier la date limite d'inscription.\"],\n  [\"Steam : s'y prendre tôt\",\"AppID payant (qui paie ?). Page « bientôt disponible » 2 semaines minimum avant la sortie, review du build = plusieurs jours. Page en ligne fin S6.\"],\n  [\"Les trous de 5-6 semaines\",\"Fin de chaque bloc : main buildable + une note sur où on en est. Après la sortie, quelqu'un surveille les avis et les bugs bloquants.\"],\n  [\"Artistes : map 2 en avance\",\"Le kit de la map 2 doit commencer dès que la map 1 est finie, sinon la MAJ 1.2 ne tient pas.\"],\n];\nconst ROLES = [\n  [\"theo\",\"theo\",\"Online (FishNet, Steam, vocal, validation serveur, builds) + level design\"],\n  [\"celian\",\"celian\",\"Joueur & gameplay : contrôleur, pistolet, pose, capture, portail, photos, data\"],\n  [\"olivier\",\"olivier\",\"PNJ, monde & présentation : foule, dégradation, glitchs, UI, menus, audio\"],\n  [\"art1\",\"art\",\"Persos & animations : PNJ, skins, anims, PNJ de l'époque 2\"],\n  [\"art2\",\"art\",\"Décors & props : anachronismes, kits d'époque, habillage, visuels Steam\"],\n  [\"tous\",\"tous\",\"Hors code : organisation, playtests, page Steam, trailer, réseaux, lancement\"],\n];\n\n// ---------- état ----------\nlet tasks = new Map(); let me=null, rev=0, editorOpen=false;          // id -> doc\nlet loaded = false, db = null, canWrite = false;\nlet LINKS = []; const TOG = new Map(); let SPRINT = null; let expandAll = false;\nconst $ = (s,r=document) => r.querySelector(s);\nconst el = (tag, cls, html) => { const e=document.createElement(tag); if(cls) e.className=cls; if(html!=null) e.innerHTML=html; return e; };\nconst esc = s => String(s??\"\").replace(/[&<>\"]/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c]));\nconst day = s => new Date(s+\"T00:00:00\");\nconst today = (()=>{ const d=new Date(); d.setHours(0,0,0,0); return d; })();\nconst wIdx = s => SW.findIndex(w=>w.s===s);\nconst CUR = (()=>{ const w = SW.find(w=> today>=day(w.a) && today<=new Date(day(w.b).getTime()+2*864e5));\n  return w ? {w, live:true} : {w: SW.find(w=>day(w.a)>today) || SW[SW.length-1], live:false}; })();\nconst name = who => PEOPLE[who] || who;\nconst isLate = t => wIdx(t.wk) < wIdx(CUR.w.s) && t.s!==\"done\";\n\nfunction list(){ return [...tasks.values()].sort((a,b)=> (wIdx(a.wk)-wIdx(b.wk)) || ((a.o??0)-(b.o??0)) || a.id.localeCompare(b.id)); }\nfunction groupsOf(arr){\n  const m = new Map();\n  for(const t of arr){ if(!m.has(t.g)) m.set(t.g,{g:t.g, gt:t.gt, who:t.who, cat:t.cat, wk:t.wk, items:[]}); m.get(t.g).items.push(t); }\n  return [...m.values()];\n}\n\n// ---------- écritures ----------\nasync function writeStatus(id, s){\n  const t = tasks.get(id); if(!t || t.s===s) return;\n  t.s = s; scheduleRender();\n  try{ await api(\"/api/tasks/\"+encodeURIComponent(id),{method:\"PATCH\",body:JSON.stringify({s})}); load(); }catch(e){ if(e.message!==\"auth\") note(\"Le statut n'a pas été enregistré : \"+e.message); }\n}\nfunction body(t){ return {g:t.g, gt:t.gt, t:t.t, who:t.who, wk:t.wk, cat:t.cat, s:t.s, o:t.o??0}; }\n\n// ---------- rendu ----------\nlet raf = 0;\nfunction scheduleRender(){ cancelAnimationFrame(raf); raf = requestAnimationFrame(renderAll); }\n\nfunction subRow(t, showWho){\n  const r = el(\"div\",\"sub\"+(t.s===\"done\"?\" done\":\"\"));\n  if(t.updated_by) r.title = \"Modifié par \"+name(t.updated_by)+\" le \"+new Date(t.updated_at).toLocaleString(\"fr-FR\",{day:\"2-digit\",month:\"2-digit\",hour:\"2-digit\",minute:\"2-digit\"});\n  const cb = el(\"input\"); cb.type=\"checkbox\"; cb.id=\"cb-\"+t.id+\"-\"+Math.random().toString(36).slice(2,6);\n  cb.checked = t.s===\"done\"; cb.disabled = !canWrite; cb.setAttribute(\"aria-label\", t.t);\n  cb.addEventListener(\"change\",()=>writeStatus(t.id, cb.checked?\"done\":\"todo\"));\n  const txt = el(\"label\",\"txt\", esc(t.t) + (t.s===\"doing\"||t.s===\"blocked\" ? `<span class=\"badge ${t.s}\">${ST[t.s]}</span>`:\"\") + (showWho?`<span class=\"who\">${esc(name(t.who))}</span>`:\"\"));\n  txt.htmlFor = cb.id;\n  r.append(cb, txt);\n  if(canWrite){ const e = el(\"button\",\"edit\",\"✎\"); e.type=\"button\"; e.title=\"Modifier\"; e.setAttribute(\"aria-label\",\"Modifier « \"+t.t+\" »\"); e.addEventListener(\"click\",()=>openEditor(t)); r.append(e); }\n  return r;\n}\nfunction groupCard(g, opts={}){\n  const done = g.items.filter(t=>t.s===\"done\").length, all = done===g.items.length;\n  const key = (opts.ctx||\"c\")+\"|\"+g.g+\"|\"+g.wk;\n  const open = TOG.has(key) ? TOG.get(key) : !all;\n  const c = el(\"div\",\"gcard c-\"+colorOf(g.who)+(all?\" alldone\":\"\")+(open?\"\":\" shut\"));\n  c.dataset.g = g.g;\n  const hd = el(\"header\",null,`<span class=\"tag\">${esc(g.cat)}</span><h4>${esc(g.gt)}</h4><span class=\"cnt\">${done}/${g.items.length}${opts.wk?\" · \"+g.wk:\"\"}</span>`);\n  hd.tabIndex = 0; hd.setAttribute(\"role\",\"button\"); hd.setAttribute(\"aria-expanded\",String(open));\n  const tog = ()=>{ const o = c.classList.toggle(\"shut\"); TOG.set(key,!o); hd.setAttribute(\"aria-expanded\",String(!o)); };\n  hd.addEventListener(\"click\",tog); hd.addEventListener(\"keydown\",e=>{ if(e.key===\"Enter\"||e.key===\" \"){ e.preventDefault(); tog(); } });\n  c.append(hd);\n  const subs = el(\"div\",\"subs\"); g.items.forEach(t=>subs.append(subRow(t, opts.showWho && (t.who!==g.who)))); c.append(subs);\n  return c;\n}\nfunction counts(ts){ const k={done:0,doing:0,blocked:0,todo:0}; ts.forEach(t=>k[t.s]=(k[t.s]||0)+1); return k; }\nfunction miniBar(ts){\n  const n=ts.length||1, k=counts(ts);\n  return `<div class=\"mbar\"><i style=\"width:${100*k.done/n}%;background:var(--done)\"></i><i style=\"width:${100*k.doing/n}%;background:var(--doing)\"></i><i style=\"width:${100*k.blocked/n}%;background:var(--blocked)\"></i></div>`;\n}\nfunction sprintState(w){ return w===CUR.w ? (CUR.live?\"En cours\":\"Prochain\") : day(w.b)<today ? \"Passé\" : \"À venir\"; }\n\nfunction renderNow(){\n  const next = MILES.find(m=>day(m[4])>=today);\n  const days = next ? Math.round((day(next[4])-today)/864e5) : 0;\n  $(\"#now\").innerHTML = `<button type=\"button\" class=\"pill-box hot clk\" id=\"pill-cur\" title=\"Voir le contenu du sprint\"><div class=\"k\">${CUR.live?\"Semaine studio en cours\":\"Prochaine semaine studio\"}</div><div class=\"v\">${CUR.w.s} <small>${CUR.w.d} · voir →</small></div></button>`\n   + (next?`<div class=\"pill-box\"><div class=\"k\">Prochain jalon</div><div class=\"v\">${esc(next[2])} <small>${next[1]} · J-${days}</small></div></div>`:\"\")\n   + (me?`<div class=\"pill-box\"><div class=\"k\">Connecté</div><div class=\"v\">${esc(me.name)} <small>${me.role===\"admin\"?`<a href=\"/admin\">Admin</a> · `:\"\"}<a href=\"#\" id=\"logout\">Déconnexion</a></small></div></div>`:\"\");\n  $(\"#pill-cur\").addEventListener(\"click\",()=>openSprint(CUR.w.s));\n  renderLinks();\n  const lo = $(\"#logout\"); if(lo) lo.addEventListener(\"click\",async e=>{ e.preventDefault(); await fetch(\"/api/logout\",{method:\"POST\"}); location.reload(); });\n}\n\nfunction renderLinks(){\n  const q = $(\"#quick\"); if(!q) return; q.innerHTML=\"\";\n  LINKS.forEach((l,i)=>{ const a = el(\"a\",\"qbtn\"+(i===0?\" main\":\"\"),`${i===0?\"📘\":\"🔗\"} ${esc(l.label)} <span class=\"ext\">↗</span>`); a.href=l.url; a.target=\"_blank\"; a.rel=\"noopener noreferrer\"; q.append(a); });\n  if(!LINKS.length && me && me.role===\"admin\"){ const a = el(\"a\",\"qbtn add\",\"+ Ajouter le lien du GDD\"); a.href=\"/admin#liens\"; q.append(a); }\n  if(LINKS.length && me && me.role===\"admin\"){ const a = el(\"a\",\"qbtn add\",\"✎\"); a.href=\"/admin#liens\"; a.title=\"Modifier les liens\"; a.setAttribute(\"aria-label\",\"Modifier les liens\"); q.append(a); }\n}\n\nfunction renderProgress(){\n  const box = $(\"#progress\"); box.innerHTML=\"\";\n  const all = list();\n  for(const c of COLS){\n    const ts = all.filter(t=>c.who.includes(t.who)); const n = ts.length||1;\n    const k = {done:0,doing:0,blocked:0}; ts.forEach(t=>{ if(k[t.s]!=null) k[t.s]++; });\n    const late = ts.filter(isLate).length;\n    const p = el(\"div\",\"prog c-\"+c.k);\n    p.innerHTML = `<div class=\"row\"><span class=\"name\"><i class=\"dot\" style=\"background:var(--c)\"></i>${esc(colLabel(c))}</span><span class=\"pct\">${Math.round(100*k.done/n)} %</span></div>\n      <div class=\"bar\"><i style=\"width:${100*k.done/n}%;background:var(--done)\"></i><i style=\"width:${100*k.doing/n}%;background:var(--doing)\"></i><i style=\"width:${100*k.blocked/n}%;background:var(--blocked)\"></i></div>\n      <div class=\"meta\">${k.done}/${ts.length} faites${late?` · <b style=\"color:var(--blocked)\">${late} en retard</b>`:\"\"}${k.blocked?` · ${k.blocked} bloquée${k.blocked>1?\"s\":\"\"}`:\"\"}</div>`;\n    box.append(p);\n  }\n}\n\nfunction renderSemaine(){\n  const p = $(\"#p-semaine\"); p.innerHTML=\"\";\n  if(!tasks.size){ p.append(el(\"div\",\"empty\",\"Aucune tâche pour l'instant. Va dans « Toutes les tâches » et clique sur « + Ajouter une tâche ».\")); return; }\n  const w = CUR.w;\n  const nt = el(\"p\",\"note\",`${CUR.live?\"Cette semaine\":\"Prochaine semaine studio\"} : <b>${w.s}</b> (${w.d})${w.m?` — jalon en fin de semaine : <b>${esc(w.m)}</b>`:\"\"}. Coche ce qui est fait, tout le monde le voit. Clique sur un groupe pour le replier. `);\n  const sb = el(\"button\",\"linkbtn\",\"Vue d'ensemble du sprint →\"); sb.type=\"button\"; sb.addEventListener(\"click\",()=>openSprint(w.s)); nt.append(sb); p.append(nt);\n  const cols = el(\"div\",\"cols\"); const all = list();\n  for(const c of COLS){\n    const col = el(\"div\",\"col c-\"+c.k);\n    const mine = all.filter(t=>c.who.includes(t.who));\n    const now = mine.filter(t=>t.wk===w.s); const late = mine.filter(isLate);\n    const gs = groupsOf(now);\n    col.append(el(\"div\",\"colh\",`<i class=\"dot\" style=\"background:var(--c)\"></i><h3>${esc(colLabel(c))}</h3><span>${now.filter(t=>t.s===\"done\").length}/${now.length}</span>`));\n    gs.forEach(g=>col.append(groupCard(g,{showWho:c.who.length>1, ctx:\"sem\"})));\n    if(!gs.length) col.append(el(\"div\",\"empty\",\"Rien cette semaine.\"));\n    if(late.length){\n      const d = el(\"details\",\"late\"); d.append(el(\"summary\",null,`En retard (${late.length})`));\n      groupsOf(late).forEach(g=>d.append(groupCard(g,{wk:true,showWho:c.who.length>1, ctx:\"late\"})));\n      col.append(d);\n    }\n    cols.append(col);\n  }\n  p.append(cols);\n}\n\nfunction renderPlanning(){\n  const p = $(\"#p-planning\"); p.innerHTML=\"\";\n  p.append(el(\"p\",\"note\",\"Une ligne = un sprint (une semaine studio, 30 h/dev). <b>Clique sur un sprint ou sur un bloc pour voir son contenu.</b> Bandes hachurées = pas de studio.\"));\n  const wrap = el(\"div\",\"plan\"); const g = el(\"div\",\"pgrid\"); const all = list();\n  g.append(el(\"div\",\"phead\",\"Semaine\"));\n  COLS.forEach(c=>g.append(el(\"div\",\"phead c-\"+c.k,`<i class=\"dot\" style=\"background:var(--c)\"></i>${esc(colLabel(c))}`)));\n  for(const w of WEEKS){\n    if(w.gap){ g.append(el(\"div\",\"gapline\",esc(w.gap))); continue; }\n    if(w.phase) g.append(el(\"div\",\"phase\",esc(w.phase)));\n    const past = day(w.b)<today && w!==CUR.w;\n    const lab = el(\"div\",\"wk\"+(w===CUR.w?\" cur\":\"\")+(past?\" row-past\":\"\"));\n    const lb = el(\"button\",null,`<h3>${w.s}</h3><div class=\"d\">${w.d}</div>${w===CUR.w?`<span class=\"now-tag\">${CUR.live?\"Maintenant\":\"Prochaine\"}</span><br>`:\"\"}${w.m?`<span class=\"mile\">◆ ${esc(w.m)}</span><br>`:\"\"}<span class=\"see\">Voir →</span>`);\n    lb.type=\"button\"; lb.setAttribute(\"aria-label\",`Voir le sprint ${w.s}`); lb.addEventListener(\"click\",()=>openSprint(w.s));\n    lab.append(lb); g.append(lab);\n    for(const c of COLS){\n      const cell = el(\"div\",past?\"row-past\":\"\"); const chips = el(\"div\",\"chips\");\n      groupsOf(all.filter(t=>t.wk===w.s && c.who.includes(t.who))).forEach(gr=>{\n        const done = gr.items.filter(t=>t.s===\"done\").length, bl = gr.items.some(t=>t.s===\"blocked\");\n        const ch = el(\"button\",\"chip c-\"+colorOf(gr.who)+(done===gr.items.length?\" cdone\":\"\")+(bl?\" cblocked\":\"\"),`<span>${esc(gr.gt)}</span><b>${done}/${gr.items.length}</b>`);\n        ch.type=\"button\"; ch.addEventListener(\"click\",()=>openSprint(w.s, gr.g)); chips.append(ch);\n      });\n      cell.append(chips); g.append(cell);\n    }\n  }\n  wrap.append(g); p.append(wrap);\n}\n\nconst F = {who:\"all\", st:\"all\", cat:\"all\", q:\"\"};\nfunction renderTaches(){\n  const p = $(\"#p-taches\");\n  const hadFocus = document.activeElement && document.activeElement.id===\"q\";\n  p.innerHTML=\"\";\n  const bar = el(\"div\",\"toolbar\");\n  for(const [k,v] of [[\"all\",\"Tout le monde\"],...COLS.map(c=>[c.k,colLabel(c)])]){\n    const b = el(\"button\",\"chipbtn\"+(k!==\"all\"?\" c-\"+k:\"\"),(k!==\"all\"?`<i class=\"dot\" style=\"background:var(--c)\"></i>`:\"\")+esc(v));\n    b.type=\"button\"; b.setAttribute(\"aria-pressed\",String(F.who===k)); b.addEventListener(\"click\",()=>{F.who=k; renderTaches();}); bar.append(b);\n  }\n  p.append(bar);\n  const bar2 = el(\"div\",\"toolbar\");\n  const sSt = el(\"select\"); sSt.id=\"f-st\"; sSt.setAttribute(\"aria-label\",\"Filtrer par statut\");\n  [[\"all\",\"Tous les statuts\"],[\"open\",\"Pas fait\"],[\"late\",\"En retard\"],...Object.entries(ST)].forEach(([k,v])=>{const o=el(\"option\",null,v);o.value=k;sSt.append(o);});\n  sSt.value=F.st; sSt.addEventListener(\"change\",()=>{F.st=sSt.value; renderTaches();});\n  const sCat = el(\"select\"); sCat.id=\"f-cat\"; sCat.setAttribute(\"aria-label\",\"Filtrer par catégorie\");\n  [[\"all\",\"Toutes les catégories\"],...CATS.map(c=>[c,c])].forEach(([k,v])=>{const o=el(\"option\",null,v);o.value=k;sCat.append(o);});\n  sCat.value=F.cat; sCat.addEventListener(\"change\",()=>{F.cat=sCat.value; renderTaches();});\n  const q = el(\"input\"); q.type=\"search\"; q.id=\"q\"; q.placeholder=\"Rechercher une tâche…\"; q.value=F.q;\n  q.addEventListener(\"input\",()=>{F.q=q.value; clearTimeout(q._t); q._t=setTimeout(renderTaches,200);});\n  bar2.append(sSt,sCat,q);\n  if(canWrite){ const add = el(\"button\",\"primary\",\"+ Ajouter une tâche\"); add.type=\"button\"; add.addEventListener(\"click\",()=>openEditor(null)); bar2.append(add); }\n  p.append(bar2);\n  if(hadFocus){ q.focus(); q.setSelectionRange(q.value.length,q.value.length); }\n\n  const col = COLS.find(c=>c.k===F.who);\n  const needle = F.q.trim().toLowerCase();\n  const keep = t => (!col || col.who.includes(t.who))\n    && (F.st===\"all\" || (F.st===\"open\" ? t.s!==\"done\" : F.st===\"late\" ? isLate(t) : t.s===F.st))\n    && (F.cat===\"all\" || t.cat===F.cat)\n    && (!needle || (t.t+\" \"+t.gt).toLowerCase().includes(needle));\n  const all = list().filter(keep);\n  const filtering = !!needle || F.st!==\"all\";\n  const nG = groupsOf(all).length;\n  const info = el(\"p\",\"note\",`${all.length} tâche${all.length>1?\"s\":\"\"} · ${nG} groupe${nG>1?\"s\":\"\"}. Clique sur un groupe pour voir ses tâches, sur un sprint pour sa vue d'ensemble. `);\n  const xa = el(\"button\",\"linkbtn\",expandAll?\"Tout replier\":\"Tout déplier\"); xa.type=\"button\"; xa.addEventListener(\"click\",()=>{ expandAll=!expandAll; [...TOG.keys()].filter(k=>k.startsWith(\"list|\")).forEach(k=>TOG.delete(k)); renderTaches(); });\n  info.append(xa); p.append(info);\n  if(!all.length){ p.append(el(\"div\",\"empty\", loaded ? \"Aucune tâche ne correspond.\" : \"Chargement…\")); return; }\n  const section = (w, ts) => {\n    const sec = el(\"div\",\"spr\"+(w&&w===CUR.w?\" cur\":\"\"));\n    if(w){\n      const full = list().filter(t=>t.wk===w.s), k = counts(full);\n      const h = el(\"button\",\"sprh\",`<span class=\"sn\">${w.s}</span><span class=\"sd\"><b>${w.d}</b> · ${sprintState(w)}${w.m?`<span class=\"sm\">◆ ${esc(w.m)}</span>`:\"\"}</span><span class=\"mini\">${miniBar(full)}<span class=\"mnum\">${k.done}/${full.length}</span></span><span class=\"go\">Voir le sprint →</span>`);\n      h.type=\"button\"; h.addEventListener(\"click\",()=>openSprint(w.s)); sec.append(h);\n    } else sec.append(el(\"div\",\"sprh\",`<span class=\"sn\">—</span><span class=\"sd\"><b>Sans semaine</b></span>`));\n    const gl = el(\"div\",\"glist\");\n    groupsOf(ts).forEach(g=>gl.append(groupRow(g, filtering)));\n    sec.append(gl); return sec;\n  };\n  for(const w of SW){ const ts = all.filter(t=>t.wk===w.s); if(ts.length) p.append(section(w, ts)); }\n  const orphan = all.filter(t=>wIdx(t.wk)<0);\n  if(orphan.length) p.append(section(null, orphan));\n}\nfunction groupRow(g, filtering){\n  const key = \"list|\"+g.g+\"|\"+g.wk;\n  const k = counts(g.items), all = k.done===g.items.length;\n  const open = TOG.has(key) ? TOG.get(key) : (expandAll || filtering);\n  const r = el(\"div\",\"grow c-\"+colorOf(g.who)+(all?\" alldone\":\"\")+(open?\" open\":\"\"));\n  const whos = [...new Set(g.items.map(t=>name(t.who)))].join(\", \");\n  const flags = (k.blocked?`<span class=\"badge blocked\">${k.blocked} bloquée${k.blocked>1?\"s\":\"\"}</span>`:\"\") + (k.doing?`<span class=\"badge doing\">${k.doing} en cours</span>`:\"\") + (g.items.some(isLate)?`<span class=\"badge blocked\">En retard</span>`:\"\");\n  const b = el(\"button\",null,`<span class=\"stripe\"></span><span class=\"gt\"><span>${esc(g.gt)}</span><span class=\"tag\">${esc(g.cat)}</span>${flags}</span><span class=\"gw\">${esc(whos)}</span><span class=\"mini\">${miniBar(g.items)}<span class=\"mnum\">${k.done}/${g.items.length}</span></span><span class=\"chev\">▶</span>`);\n  b.type=\"button\"; b.setAttribute(\"aria-expanded\",String(open));\n  const subs = el(\"div\",\"subs\"); subs.hidden = !open;\n  b.addEventListener(\"click\",()=>{\n    const o = !r.classList.contains(\"open\"); r.classList.toggle(\"open\",o); subs.hidden=!o; b.setAttribute(\"aria-expanded\",String(o)); TOG.set(key,o);\n    if(o && !subs.childElementCount) g.items.forEach(t=>subs.append(subRow(t, t.who!==g.who)));\n  });\n  if(open) g.items.forEach(t=>subs.append(subRow(t, t.who!==g.who)));\n  r.append(b, subs); return r;\n}\n\nfunction renderJalons(){\n  const p = $(\"#p-jalons\"); p.innerHTML=\"\";\n  const nextIdx = MILES.findIndex(m=>day(m[4])>=today);\n  const box = el(\"div\",\"miles\");\n  MILES.forEach((m,i)=>{\n    const cls = (nextIdx<0||i<nextIdx) ? \"past\" : i===nextIdx ? \"next\" : \"later\";\n    const row = el(\"div\",\"ms clk\"+(cls===\"next\"?\" next\":\"\"),`<div class=\"when\">${m[0]}<small>${m[1]}</small></div><div><h3>${esc(m[2])}</h3><p>${esc(m[3])}</p></div><span class=\"state st-${cls}\">${cls===\"past\"?\"Date passée\":cls===\"next\"?\"Prochain\":\"À venir\"}</span>`);\n    row.tabIndex=0; row.setAttribute(\"role\",\"button\"); row.title=\"Voir le contenu du sprint \"+m[0];\n    row.addEventListener(\"click\",()=>openSprint(m[0])); row.addEventListener(\"keydown\",e=>{ if(e.key===\"Enter\"){ openSprint(m[0]); } });\n    box.append(row);\n  });\n  p.append(box);\n}\n\nfunction renderInfos(){\n  const p = $(\"#p-infos\"); p.innerHTML=\"\";\n  const h1 = el(\"h2\",null,\"À lire avant tout\"); h1.style.cssText=\"font-size:24px;margin-bottom:10px\"; p.append(h1);\n  const a = el(\"div\",\"alerts\"); ALERTS.forEach(x=>a.append(el(\"div\",\"alert\",`<h3>${esc(x[0])}</h3><p>${esc(x[1])}</p>`))); p.append(a);\n  const h2 = el(\"h2\",null,\"Qui fait quoi\"); h2.style.cssText=\"font-size:24px;margin-bottom:10px\"; p.append(h2);\n  const r = el(\"div\",\"roles\"); ROLES.forEach(([who,c,txt])=>r.append(el(\"div\",\"role c-\"+c,`<h3>${esc(name(who))}</h3><p>${esc(txt)}</p>`))); p.append(r);\n  if(me && me.role===\"admin\") p.append(el(\"p\",\"note\",\"Pour renommer les artistes ou donner les codes d’accès : <a href=\\\"/admin\\\">page admin</a>.\"));\n}\n\nfunction renderAll(){\n  renderNow(); renderProgress();\n  if(!loaded){ return; }\n  renderSemaine(); renderPlanning(); renderTaches(); renderJalons(); renderInfos();\n  if(SPRINT) renderSprint();\n}\n\n// ---------- fenêtre sprint ----------\nfunction openSprint(s, focusG){\n  if(wIdx(s)<0) return;\n  SPRINT = {s, focus: focusG||null}; renderSprint(true);\n  try{ history.replaceState(null,\"\",\"#sprint-\"+s); }catch(e){}\n}\nfunction closeSprint(){\n  SPRINT=null; const b=$(\"#sprint\"); b.hidden=true; b.innerHTML=\"\"; document.body.style.overflow=\"\";\n  try{ history.replaceState(null,\"\",location.pathname); }catch(e){}\n}\nfunction renderSprint(first){\n  const box = $(\"#sprint\"); const old = box.querySelector(\".scrim\"); const top = old ? old.scrollTop : 0;\n  const w = SW[wIdx(SPRINT.s)]; const i = wIdx(w.s);\n  const ts = list().filter(t=>t.wk===w.s); const k = counts(ts); const n = ts.length||1;\n  const mile = MILES.find(m=>m[0]===w.s);\n  const phase = (()=>{ let ph=\"\"; for(const x of WEEKS){ if(x.phase) ph=x.phase; if(x===w) return ph; } return ph; })();\n  box.hidden=false; box.innerHTML=\"\"; document.body.style.overflow=\"hidden\";\n  const scrim = el(\"div\",\"scrim\"); const sh = el(\"div\",\"sheet\"); sh.setAttribute(\"role\",\"dialog\"); sh.setAttribute(\"aria-modal\",\"true\"); sh.setAttribute(\"aria-label\",\"Sprint \"+w.s);\n  const st = sprintState(w);\n  const hd = el(\"header\");\n  hd.innerHTML = `<div class=\"sh1\"><div><h2>Sprint ${w.s}<small>${w.d}</small></h2><div class=\"muted\" style=\"margin-top:4px\">${esc(phase)} · <span class=\"st${st===\"En cours\"||st===\"Prochain\"?\" live\":\"\"}\">${st}</span></div></div><span class=\"sp\"></span>\n    <div class=\"navb\"><button type=\"button\" class=\"ghost small\" id=\"sp-prev\" ${i<=0?\"disabled\":\"\"}>← ${i>0?SW[i-1].s:\"\"}</button><button type=\"button\" class=\"ghost small\" id=\"sp-next\" ${i>=SW.length-1?\"disabled\":\"\"}>${i<SW.length-1?SW[i+1].s:\"\"} →</button><button type=\"button\" class=\"ghost small\" id=\"sp-close\" aria-label=\"Fermer\">✕</button></div></div>\n    ${mile?`<div class=\"milebox\"><b>◆ Jalon de fin de sprint : ${esc(mile[2])}</b><br>${esc(mile[3])}</div>`:\"\"}\n    <div class=\"stats\"><div class=\"bar\"><i style=\"width:${100*k.done/n}%;background:var(--done)\"></i><i style=\"width:${100*k.doing/n}%;background:var(--doing)\"></i><i style=\"width:${100*k.blocked/n}%;background:var(--blocked)\"></i></div>\n      <span><b>${k.done}/${ts.length}</b> faites</span><span><b>${k.doing}</b> en cours</span><span${k.blocked?' style=\"color:var(--blocked)\"':\"\"}><b${k.blocked?' style=\"color:var(--blocked)\"':\"\"}>${k.blocked}</b> bloquée${k.blocked>1?\"s\":\"\"}</span></div>`;\n  sh.append(hd);\n  const body = el(\"div\",\"sb\");\n  if(!ts.length) body.append(el(\"div\",\"empty\",\"Aucune tâche prévue sur ce sprint.\"));\n  for(const c of COLS){\n    const mine = ts.filter(t=>c.who.includes(t.who)); if(!mine.length) continue;\n    const col = el(\"div\",\"col c-\"+c.k);\n    col.append(el(\"div\",\"colh\",`<i class=\"dot\" style=\"background:var(--c)\"></i><h3>${esc(colLabel(c))}</h3><span>${mine.filter(t=>t.s===\"done\").length}/${mine.length}</span>`));\n    groupsOf(mine).forEach(g=>{ const card = groupCard(g,{showWho:c.who.length>1, ctx:\"spr\"}); if(SPRINT.focus===g.g){ card.classList.add(\"hl\"); card.classList.remove(\"shut\"); } col.append(card); });\n    body.append(col);\n  }\n  sh.append(body); scrim.append(sh); box.append(scrim);\n  scrim.addEventListener(\"click\",e=>{ if(e.target===scrim) closeSprint(); });\n  $(\"#sp-close\").addEventListener(\"click\",closeSprint);\n  $(\"#sp-prev\").addEventListener(\"click\",()=>{ if(i>0) openSprint(SW[i-1].s); });\n  $(\"#sp-next\").addEventListener(\"click\",()=>{ if(i<SW.length-1) openSprint(SW[i+1].s); });\n  if(first){\n    const f = SPRINT.focus && sh.querySelector(`.gcard.hl`);\n    if(f) setTimeout(()=>f.scrollIntoView({block:\"center\"}),0); else $(\"#sp-close\").focus();\n  } else scrim.scrollTop = top;\n}\ndocument.addEventListener(\"keydown\",e=>{\n  if(e.key!==\"Escape\" || !SPRINT || editorOpen) return; closeSprint();\n}, true);\ndocument.addEventListener(\"keydown\",e=>{\n  if(!SPRINT || editorOpen || e.target.closest(\"input,select,textarea\")) return;\n  const i = wIdx(SPRINT.s);\n  if(e.key===\"ArrowLeft\" && i>0) openSprint(SW[i-1].s);\n  if(e.key===\"ArrowRight\" && i<SW.length-1) openSprint(SW[i+1].s);\n});\n\n// ---------- éditeur ----------\nfunction openEditor(t){\n  const isNew = !t;\n  const d = t ? {...t} : {id:null, t:\"\", g:\"\", gt:\"\", who: (COLS.find(c=>c.k===F.who)?.who[0]) || \"theo\", wk: CUR.w.s, cat:\"Gameplay\", s:\"todo\"};\n  const groups = groupsOf(list()).map(g=>[g.g,g.gt,g.wk]);\n  const box = $(\"#editor\"); box.hidden=false; box.innerHTML=\"\"; editorOpen=true;\n  const scrim = el(\"div\",\"scrim\"); const f = el(\"form\",\"form\"); f.setAttribute(\"role\",\"dialog\"); f.setAttribute(\"aria-modal\",\"true\");\n  f.innerHTML = `<h2>${isNew?\"Nouvelle tâche\":\"Modifier la tâche\"}</h2>\n    <label>Tâche<input id=\"e-t\" required maxlength=\"200\"></label>\n    <label>Groupe<select id=\"e-g\"></select></label>\n    <label id=\"e-ngw\" hidden>Nom du nouveau groupe<input id=\"e-ng\" maxlength=\"80\"></label>\n    <div class=\"two\"><label>Qui<select id=\"e-who\"></select></label><label>Semaine<select id=\"e-wk\"></select></label></div>\n    <div class=\"two\"><label>Catégorie<select id=\"e-cat\"></select></label><label>Statut<select id=\"e-s\"></select></label></div>\n    <p class=\"err\" id=\"e-err\" hidden></p>\n    <div class=\"actions\">${isNew?\"\":`<button type=\"button\" class=\"danger\" id=\"e-del\">Supprimer</button>`}<span class=\"sp\"></span><button type=\"button\" class=\"ghost\" id=\"e-cancel\">Annuler</button><button type=\"submit\" class=\"primary\">Enregistrer</button></div>`;\n  scrim.append(f); box.append(scrim);\n  const opt = (sel, pairs, val) => { pairs.forEach(([k,v])=>{const o=el(\"option\",null,esc(v));o.value=k;sel.append(o);}); sel.value=val; };\n  $(\"#e-t\").value = d.t;\n  opt($(\"#e-g\"), [[\"__new\",\"+ Nouveau groupe…\"],...groups.map(([g,gt,wk])=>[g,`${gt} (${wk})`])], d.g || \"__new\");\n  opt($(\"#e-who\"), Object.keys(PEOPLE).map(k=>[k,PEOPLE[k]]), d.who);\n  opt($(\"#e-wk\"), SW.map(w=>[w.s,`${w.s} — ${w.d}`]), d.wk);\n  opt($(\"#e-cat\"), CATS.map(c=>[c,c]), CATS.includes(d.cat)?d.cat:\"Gameplay\");\n  opt($(\"#e-s\"), Object.entries(ST), d.s);\n  const syncG = ()=>{ $(\"#e-ngw\").hidden = $(\"#e-g\").value!==\"__new\"; };\n  $(\"#e-g\").addEventListener(\"change\",()=>{ syncG(); const gg = groups.find(x=>x[0]===$(\"#e-g\").value); if(gg && isNew){ const any=[...tasks.values()].find(x=>x.g===gg[0]); if(any){ $(\"#e-who\").value=any.who; $(\"#e-wk\").value=any.wk; $(\"#e-cat\").value=CATS.includes(any.cat)?any.cat:\"Gameplay\"; } } });\n  syncG();\n  const close = ()=>{ box.hidden=true; box.innerHTML=\"\"; editorOpen=false; };\n  $(\"#e-cancel\").addEventListener(\"click\",close);\n  scrim.addEventListener(\"click\",e=>{ if(e.target===scrim) close(); });\n  f.addEventListener(\"keydown\",e=>{ if(e.key===\"Escape\") close(); });\n  const del = $(\"#e-del\");\n  if(del) del.addEventListener(\"click\",async()=>{\n    if(del.dataset.armed!==\"1\"){ del.dataset.armed=\"1\"; del.textContent=\"Confirmer la suppression\"; return; }\n    tasks.delete(d.id); close(); scheduleRender();\n    try{ await api(\"/api/tasks/\"+encodeURIComponent(d.id),{method:\"DELETE\"}); load(); }catch(e){ if(e.message!==\"auth\") note(\"La suppression a échoué : \"+e.message); }\n  });\n  f.addEventListener(\"submit\",async e=>{\n    e.preventDefault();\n    const title = $(\"#e-t\").value.trim(); const gsel = $(\"#e-g\").value; const ng = $(\"#e-ng\").value.trim();\n    const err = $(\"#e-err\");\n    if(!title){ err.textContent=\"Donne un nom à la tâche.\"; err.hidden=false; return; }\n    if(gsel===\"__new\" && !ng){ err.textContent=\"Donne un nom au nouveau groupe, ou choisis un groupe existant.\"; err.hidden=false; return; }\n    let g = gsel, gt;\n    if(gsel===\"__new\"){ g = \"N\"+Date.now().toString(36); gt = ng; }\n    else gt = (groups.find(x=>x[0]===gsel)||[])[1] || d.gt;\n    const sameG = [...tasks.values()].filter(x=>x.g===g);\n    const o = (!isNew && d.g===g) ? d.o : (sameG.length ? Math.max(...sameG.map(x=>x.o||0))+1 : 900000 + Date.now()%100000);\n    const doc = {g, gt, t:title, who:$(\"#e-who\").value, wk:$(\"#e-wk\").value, cat:$(\"#e-cat\").value, s:$(\"#e-s\").value, o};\n    if(!isNew){ tasks.set(d.id,{...d,...doc}); }\n    close(); scheduleRender();\n    try{\n      if(isNew) await api(\"/api/tasks\",{method:\"POST\",body:JSON.stringify(doc)});\n      else await api(\"/api/tasks/\"+encodeURIComponent(d.id),{method:\"PATCH\",body:JSON.stringify(doc)});\n      load();\n    }catch(e2){ if(e2.message!==\"auth\") note(\"La tâche n'a pas été enregistrée : \"+e2.message); }\n  });\n  $(\"#e-t\").focus();\n}\n\n// ---------- onglets ----------\nconst TABS = [\"semaine\",\"planning\",\"taches\",\"jalons\",\"infos\",\"regles\"];\nfunction show(tab){\n  if(!TABS.includes(tab)) tab=\"semaine\";\n  document.querySelectorAll(\".tabs button\").forEach(b=>b.setAttribute(\"aria-selected\", String(b.dataset.tab===tab)));\n  document.querySelectorAll(\"[data-panel]\").forEach(s=>s.hidden = s.dataset.panel!==tab);\n  try{ localStorage.setItem(\"anachro-tab\",tab); }catch(e){}\n}\ndocument.querySelectorAll(\".tabs button\").forEach(b=>b.addEventListener(\"click\",()=>show(b.dataset.tab)));\nfunction note(msg){ const n=$(\"#dbnote\"); n.textContent=msg; n.hidden=false; }\n\nrenderNow(); renderProgress(); renderJalons();\nlet start = (location.hash||\"\").slice(1); if(!start){ try{ start = localStorage.getItem(\"anachro-tab\")||\"\"; }catch(e){} }\nshow(start);\n\n// ---------- serveur (Cloudflare Worker) ----------\n\nasync function api(path, opts={}){\n  const r = await fetch(path,{credentials:\"same-origin\",headers:{\"content-type\":\"application/json\"},...opts});\n  let j={}; try{ j=await r.json(); }catch(e){}\n  if(r.status===401 && path!==\"/api/login\"){ showLogin(); throw new Error(\"auth\"); }\n  if(!r.ok) throw new Error(j.error||(\"Erreur \"+r.status));\n  return j;\n}\nasync function load(){\n  const j = await api(\"/api/tasks\"+(rev?\"?since=\"+rev:\"\"));\n  if(j.unchanged) return;\n  rev=j.rev; me=j.me; loaded=true;\n  canWrite = !!me && me.role !== \"viewer\";\n  if(me && me.role===\"viewer\") note(\"Mode spectateur : tu peux tout consulter, mais rien modifier.\");\n  (j.people||[]).forEach(p=>{ if(p.role!==\"viewer\") PEOPLE[p.id]=p.name; });\n  tasks = new Map(j.tasks.map(t=>[t.id,{...t, s: ST[t.s]?t.s:\"todo\"}]));\n  LINKS = Array.isArray(j.links) ? j.links : [];\n  const hs = (location.hash.match(/^#sprint-(S\\d+)$/)||[])[1];\n  if(hs && !SPRINT && !load.didHash){ load.didHash=true; openSprint(hs); }\n  scheduleRender();\n}\nsetInterval(()=>{ if(!document.hidden && me && !editorOpen) load().catch(()=>{}); }, 8000);\ndocument.addEventListener(\"visibilitychange\",()=>{ if(!document.hidden && me) load().catch(()=>{}); });\n\nlet loginOpen=false;\nasync function showLogin(){\n  if(loginOpen) return; loginOpen=true;\n  let st={setup:false,people:[]}; try{ st = await (await fetch(\"/api/state\")).json(); }catch(e){}\n  const box = $(\"#editor\"); box.hidden=false; box.innerHTML=\"\"; editorOpen=true;\n  const scrim = el(\"div\",\"scrim\"); const f = el(\"form\",\"form\");\n  if(st.setup){\n    f.innerHTML = `<h2>Première configuration</h2><p class=\"note\" style=\"margin:0\">Crée le mot de passe admin de Théo (6 caractères minimum). Tu donneras ensuite un code à chacun depuis la page admin.</p>\n      <label>Mot de passe admin<input id=\"l-pin\" type=\"password\" autocomplete=\"new-password\" minlength=\"6\" required></label><p class=\"err\" id=\"l-err\" hidden></p>\n      <div class=\"actions\"><span class=\"sp\"></span><button class=\"primary\" type=\"submit\">Créer</button></div>`;\n  } else {\n    f.innerHTML = `<h2>Connexion</h2><label>Qui es-tu ?<select id=\"l-user\"></select></label>\n      <label>Code<input id=\"l-pin\" type=\"password\" autocomplete=\"current-password\" required></label><p class=\"err\" id=\"l-err\" hidden></p>\n      <div class=\"actions\"><span class=\"sp\"></span><button class=\"primary\" type=\"submit\">Se connecter</button></div>`;\n  }\n  scrim.append(f); box.append(scrim);\n  if(!st.setup){\n    const sel=$(\"#l-user\"); st.people.forEach(p=>{const o=el(\"option\",null,esc(p.name)); o.value=p.id; sel.append(o);});\n    try{ const last=localStorage.getItem(\"anachro-user\"); if(last) sel.value=last; }catch(e){}\n  }\n  $(\"#l-pin\").focus();\n  f.addEventListener(\"submit\",async e=>{\n    e.preventDefault(); const er=$(\"#l-err\"); er.hidden=true;\n    try{\n      if(st.setup) await api(\"/api/setup\",{method:\"POST\",body:JSON.stringify({pin:$(\"#l-pin\").value})});\n      else {\n        await api(\"/api/login\",{method:\"POST\",body:JSON.stringify({user:$(\"#l-user\").value,pin:$(\"#l-pin\").value})});\n        try{ localStorage.setItem(\"anachro-user\",$(\"#l-user\").value); }catch(e){}\n      }\n      box.hidden=true; box.innerHTML=\"\"; editorOpen=false; loginOpen=false; rev=0; await load();\n    }catch(x){ er.textContent=x.message; er.hidden=false; }\n  });\n}\nload().catch(e=>{ if(e.message!==\"auth\") $(\"#p-semaine\").innerHTML=`<div class=\"empty\">Impossible de charger les tâches : ${esc(e.message)}</div>`; });\n</script>\n</body></html>";
const ADMIN_HTML = "<!doctype html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"robots\" content=\"noindex\"><title>Anachro Admin</title><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,800&family=IBM+Plex+Sans:wght@400;500;600&family=JetBrains+Mono:wght@500;700&display=swap\">\n<style>\n/* Layout : en-tête (semaine en cours + jalon) → avancement par personne → onglets → une vue à la fois. Une couleur par personne. */\n:root{\n  --bg:#F2F3F6; --surface:#FFFFFF; --sunk:#E7E9EF; --fg:#151821; --muted:#5D6375; --line:#D3D7E0;\n  --accent:#C2410C; --accent-soft:#FBE3D6;\n  --theo:#2F5FD0; --theo-soft:#E2EAFB; --celian:#1F8A5B; --celian-soft:#DDF3E8; --olivier:#B4590E; --olivier-soft:#FBE9D8;\n  --art:#8B3FB8; --art-soft:#F1E3F8; --tous:#4B5263; --tous-soft:#E4E6EC;\n  --doing:#B7860B; --doing-soft:#FBF0CF; --done:#1F8A5B; --done-soft:#DDF3E8; --blocked:#C0262D; --blocked-soft:#FBDADB;\n  --scrim:rgba(15,18,26,.45);\n  --f-display:\"Bricolage Grotesque\",ui-sans-serif,system-ui,sans-serif;\n  --f-body:\"IBM Plex Sans\",ui-sans-serif,system-ui,sans-serif;\n  --f-mono:\"JetBrains Mono\",ui-monospace,SFMono-Regular,Menlo,monospace;\n  --r:10px;\n}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){\n  --bg:#12141A; --surface:#1B1E26; --sunk:#242833; --fg:#E9EBF1; --muted:#9BA1B3; --line:#323746;\n  --accent:#F08A4B; --accent-soft:#3A2418;\n  --theo:#7FA3F5; --theo-soft:#1D2742; --celian:#5CC994; --celian-soft:#16301F; --olivier:#F0A061; --olivier-soft:#3A2614;\n  --art:#C990EC; --art-soft:#2E1F3A; --tous:#AEB4C4; --tous-soft:#262A35;\n  --doing:#E9BC45; --doing-soft:#3A3014; --done:#5CC994; --done-soft:#16301F; --blocked:#F0686E; --blocked-soft:#3D1A1C;\n  --scrim:rgba(0,0,0,.6); color-scheme:dark}}\n:root[data-theme=\"dark\"]{\n  --bg:#12141A; --surface:#1B1E26; --sunk:#242833; --fg:#E9EBF1; --muted:#9BA1B3; --line:#323746;\n  --accent:#F08A4B; --accent-soft:#3A2418;\n  --theo:#7FA3F5; --theo-soft:#1D2742; --celian:#5CC994; --celian-soft:#16301F; --olivier:#F0A061; --olivier-soft:#3A2614;\n  --art:#C990EC; --art-soft:#2E1F3A; --tous:#AEB4C4; --tous-soft:#262A35;\n  --doing:#E9BC45; --doing-soft:#3A3014; --done:#5CC994; --done-soft:#16301F; --blocked:#F0686E; --blocked-soft:#3D1A1C;\n  --scrim:rgba(0,0,0,.6); color-scheme:dark}\n*{box-sizing:border-box}\nbody{background:var(--bg);color:var(--fg);font-family:var(--f-body);font-size:16px;line-height:1.5}\n.wrap{max-width:1320px;margin:0 auto;padding-inline:20px;padding-block:24px 64px}\nh1,h2,h3{font-family:var(--f-display);margin:0;text-wrap:balance;letter-spacing:-.01em}\nbutton{font-family:inherit}\n.muted{color:var(--muted)}\n\n.top{display:grid;grid-template-columns:1fr auto;gap:16px 24px;align-items:end;margin-bottom:20px}\n.top h1{font-size:clamp(30px,5vw,44px);font-weight:800}\n.top .sub{color:var(--muted);margin-top:2px}\n.now{display:flex;gap:12px;flex-wrap:wrap}\n.pill-box{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:10px 14px;min-width:0}\n.pill-box .k{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);font-weight:600}\n.pill-box .v{font-family:var(--f-display);font-size:20px;font-weight:600;line-height:1.2}\n.pill-box .v small{font-family:var(--f-body);font-size:14px;color:var(--muted);font-weight:500}\n.pill-box.hot{border-color:var(--accent);background:var(--accent-soft)}\n\n.progress{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-bottom:18px}\n.prog{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:10px 12px;min-width:0}\n.prog .row{display:flex;justify-content:space-between;align-items:baseline;gap:8px}\n.prog .name{font-weight:600;font-size:16px;display:flex;align-items:center;gap:8px;min-width:0}\n.prog .pct{font-family:var(--f-mono);font-weight:700;font-variant-numeric:tabular-nums}\n.bar{height:8px;background:var(--sunk);border-radius:99px;overflow:hidden;margin-top:8px;display:flex}\n.bar i{display:block;height:100%}\n.prog .meta{font-size:13px;color:var(--muted);margin-top:6px;font-variant-numeric:tabular-nums}\n.dot{width:10px;height:10px;border-radius:50%;display:inline-block;flex:none}\n\n.tabs{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:var(--bg);display:flex;gap:6px;overflow-x:auto;padding-block:8px;margin-bottom:16px;border-bottom:1px solid var(--line)}\n.tabs button{font:600 15px var(--f-body);color:var(--muted);background:none;border:0;padding:9px 14px;border-radius:8px;cursor:pointer;white-space:nowrap}\n.tabs button:hover{background:var(--sunk);color:var(--fg)}\n.tabs button[aria-selected=\"true\"]{background:var(--fg);color:var(--bg)}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n\n.note{font-size:14px;color:var(--muted);margin:0 0 14px}\n.banner{background:var(--doing-soft);border:1px solid var(--doing);border-radius:var(--r);padding:10px 14px;font-size:14px;margin-bottom:16px}\n.empty{padding:18px;color:var(--muted);font-size:15px;background:var(--surface);border:1px dashed var(--line);border-radius:var(--r)}\n\n/* Cette semaine */\n.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px;align-items:start}\n.col{min-width:0;display:flex;flex-direction:column;gap:10px}\n.colh{display:flex;align-items:center;gap:10px;padding:4px 2px;border-bottom:3px solid var(--c);}\n.colh h3{font-size:21px}\n.colh span{font-size:13px;color:var(--muted);margin-left:auto}\n\n.gcard{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;min-width:0}\n.gcard>header{display:flex;gap:8px;align-items:baseline;padding:10px 12px 6px;flex-wrap:wrap}\n.gcard>header h4{margin:0;font-size:16px;font-weight:600}\n.gcard>header .cnt{margin-left:auto;font-family:var(--f-mono);font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums}\n.tag{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;padding:2px 6px;border-radius:5px;background:var(--c-soft);color:var(--c)}\n.gcard.alldone>header h4{text-decoration:line-through;color:var(--muted)}\n.subs{display:flex;flex-direction:column;padding:0 4px 6px}\n.sub{display:flex;gap:10px;align-items:flex-start;padding:6px 8px;border-radius:7px}\n.sub:hover{background:var(--sunk)}\n.sub input[type=checkbox]{width:18px;height:18px;margin:2px 0 0;accent-color:var(--done);flex:none;cursor:pointer}\n.sub .txt{flex:1;min-width:0;font-size:15px;line-height:1.4}\n.sub.done .txt{text-decoration:line-through;color:var(--muted)}\n.sub .who{font-size:12px;color:var(--muted);display:block}\n.badge{display:inline-block;font-size:11px;font-weight:700;padding:1px 6px;border-radius:5px;margin-left:6px;vertical-align:1px}\n.badge.doing{background:var(--doing-soft);color:var(--doing)}\n.badge.blocked{background:var(--blocked-soft);color:var(--blocked)}\n.edit{flex:none;border:0;background:none;color:var(--muted);cursor:pointer;font-size:15px;padding:0 4px;border-radius:5px;opacity:.55}\n.sub:hover .edit,.edit:focus-visible{opacity:1}\n.late{margin-top:4px}\n.late>summary{cursor:pointer;font-weight:600;color:var(--blocked);font-size:14px;padding:4px 2px}\n\n/* Planning */\n.plan{overflow-x:auto}\n.pgrid{display:grid;grid-template-columns:120px repeat(5,minmax(170px,1fr));min-width:1000px}\n.pgrid>div{padding:10px 8px;border-bottom:1px solid var(--line);min-width:0}\n.phead{position:sticky;top:0;background:var(--bg);font-weight:700;border-bottom:2px solid var(--fg)!important;display:flex;gap:6px;align-items:center}\n.wk h3{font-size:22px;font-weight:800}\n.wk .d{font-size:13px;color:var(--muted)}\n.wk.cur h3{color:var(--accent)}\n.row-past{opacity:.5}\n.mile{display:inline-block;margin-top:4px;font-size:12px;font-weight:700;padding:2px 7px;border-radius:6px;background:var(--accent-soft);color:var(--accent)}\n.now-tag{display:inline-block;margin-top:4px;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:2px 7px;border-radius:6px;background:var(--accent);color:var(--bg)}\n.chips{display:flex;flex-direction:column;gap:5px}\n.chip{display:flex;gap:6px;justify-content:space-between;align-items:baseline;padding:6px 8px;border-radius:7px;font-size:13.5px;line-height:1.3;background:var(--c-soft);color:var(--fg);border:1px solid transparent}\n.chip b{font-family:var(--f-mono);font-size:11.5px;color:var(--c);flex:none;font-variant-numeric:tabular-nums}\n.chip.cdone{opacity:.55;text-decoration:line-through}\n.chip.cblocked{border-color:var(--blocked)}\n.gapline{grid-column:1/-1;padding:9px 8px!important;font-size:13.5px;color:var(--muted);background:repeating-linear-gradient(135deg,transparent 0 8px,var(--sunk) 8px 9px)}\n.phase{grid-column:1/-1;font-size:12px;text-transform:uppercase;letter-spacing:.1em;font-weight:700;color:var(--accent);padding-top:22px!important}\n\n/* Toutes les tâches */\n.toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:14px}\n.chipbtn{font:600 14px var(--f-body);border:1.5px solid var(--line);background:var(--surface);color:var(--fg);padding:6px 12px;border-radius:99px;cursor:pointer;display:flex;gap:6px;align-items:center}\n.chipbtn[aria-pressed=\"true\"]{border-color:var(--fg);background:var(--fg);color:var(--bg)}\n.toolbar select,.toolbar input,.form select,.form input{font:500 14px var(--f-body);padding:7px 10px;border:1.5px solid var(--line);border-radius:8px;background:var(--surface);color:var(--fg);min-width:0}\n.toolbar input[type=search]{flex:1 1 200px}\n.primary{font:600 14px var(--f-body);background:var(--accent);color:#fff;border:0;border-radius:8px;padding:8px 14px;cursor:pointer}\n.ghost{font:600 14px var(--f-body);background:none;color:var(--fg);border:1.5px solid var(--line);border-radius:8px;padding:8px 14px;cursor:pointer}\n.danger{font:600 14px var(--f-body);background:none;color:var(--blocked);border:1.5px solid var(--blocked);border-radius:8px;padding:8px 14px;cursor:pointer}\n.wgroup{margin-bottom:22px}\n.wgroup>h3{font-size:19px;margin-bottom:8px;display:flex;gap:10px;align-items:baseline;flex-wrap:wrap}\n.wgroup>h3 small{font:500 14px var(--f-body);color:var(--muted)}\n.ggrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:10px;align-items:start}\n\n/* Jalons / infos */\n.miles{display:flex;flex-direction:column;gap:10px}\n.ms{display:grid;grid-template-columns:110px minmax(0,1fr) auto;gap:16px;align-items:center;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px}\n.ms .when{font-family:var(--f-display);font-weight:800;font-size:22px;line-height:1.1}\n.ms .when small{display:block;font:500 14px var(--f-body);color:var(--muted)}\n.ms h3{font-size:19px}\n.ms p{margin:2px 0 0;color:var(--muted);font-size:15px}\n.ms .state{font-size:13px;font-weight:700;padding:4px 10px;border-radius:99px;white-space:nowrap}\n.ms.next{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}\n.st-past{background:var(--sunk);color:var(--muted)} .st-next{background:var(--accent);color:var(--bg)} .st-later{background:var(--sunk);color:var(--fg)}\n.alerts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:28px}\n.alert{background:var(--surface);border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:var(--r);padding:14px 16px;min-width:0}\n.alert h3{font-size:18px;margin-bottom:4px}\n.alert p{margin:0;color:var(--muted);font-size:15px}\n.roles{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-bottom:24px}\n.role{border-radius:var(--r);padding:14px 16px;min-width:0;background:var(--c-soft)}\n.role h3{font-size:21px;color:var(--c)}\n.role p{margin:4px 0 0;font-size:15px}\n.rename{display:flex;gap:10px;flex-wrap:wrap;align-items:end}\n.rename label{display:flex;flex-direction:column;gap:4px;font-size:13px;font-weight:600;color:var(--muted)}\n\n/* Règles */\ndetails.rule{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);margin-bottom:10px;overflow:hidden}\ndetails.rule>summary{cursor:pointer;padding:14px 16px;font-family:var(--f-display);font-weight:600;font-size:20px;list-style:none;display:flex;justify-content:space-between;gap:12px}\ndetails.rule>summary::-webkit-details-marker{display:none}\ndetails.rule>summary::after{content:\"+\";font-family:var(--f-mono);color:var(--muted)}\ndetails.rule[open]>summary::after{content:\"–\"}\n.rb{padding:0 16px 16px}\n.rb ol,.rb ul{margin:0;padding-left:22px}\n.rb li{margin:6px 0}\n.rb li b{font-weight:600}\n.rb li span{color:var(--muted)}\npre.tree{font-family:var(--f-mono);font-size:13.5px;background:var(--sunk);border-radius:8px;padding:14px;overflow-x:auto;margin:0 0 10px;line-height:1.55}\n.tbl{overflow-x:auto}\ntable{border-collapse:collapse;width:100%;font-size:15px}\nth,td{text-align:left;padding:9px 10px;border-bottom:1px solid var(--line);vertical-align:top}\nth{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}\ntd code,li code,p code{font-family:var(--f-mono);font-size:13px;background:var(--sunk);padding:1px 5px;border-radius:4px}\n\n/* Éditeur */\n.scrim{position:fixed;inset:0;background:var(--scrim);z-index:20;display:flex;align-items:flex-start;justify-content:center;padding:max(40px,env(safe-area-inset-top,0px)) 16px 16px;overflow-y:auto}\n.form{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:20px;width:min(560px,100%);display:flex;flex-direction:column;gap:12px}\n.form h2{font-size:22px}\n.form label{display:flex;flex-direction:column;gap:4px;font-size:13px;font-weight:600;color:var(--muted)}\n.form .two{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.form .actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:4px}\n.form .actions .sp{flex:1}\n.form .err{color:var(--blocked);font-size:14px;margin:0}\n\n.c-theo{--c:var(--theo);--c-soft:var(--theo-soft)} .c-celian{--c:var(--celian);--c-soft:var(--celian-soft)} .c-olivier{--c:var(--olivier);--c-soft:var(--olivier-soft)}\n.c-art{--c:var(--art);--c-soft:var(--art-soft)} .c-tous{--c:var(--tous);--c-soft:var(--tous-soft)}\n\n\n/* Liens rapides (GDD…) */\n.quick{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}\n.qbtn{display:inline-flex;align-items:center;gap:7px;font:600 14px var(--f-body);text-decoration:none;color:var(--fg);background:var(--surface);border:1.5px solid var(--line);border-radius:99px;padding:6px 14px}\n.qbtn:hover{border-color:var(--fg)}\n.qbtn.main{background:var(--fg);color:var(--bg);border-color:var(--fg)}\n.qbtn .ext{font-size:12px;opacity:.7}\n.qbtn.add{border-style:dashed;color:var(--muted)}\na{color:var(--accent)}\n.linkbtn{font:inherit;color:var(--accent);background:none;border:0;padding:0;cursor:pointer;text-decoration:underline;text-underline-offset:2px}\n.pill-box.clk{cursor:pointer;text-align:left;font:inherit;color:inherit}\n.pill-box.clk:hover{box-shadow:0 0 0 2px var(--accent)}\n\n/* Groupes repliables */\n.gcard>header{cursor:pointer;user-select:none}\n.gcard>header::after{content:\"▾\";font-size:12px;color:var(--muted);margin-left:2px;transition:transform .15s}\n.gcard.shut>header::after{transform:rotate(-90deg)}\n.gcard.shut>.subs{display:none}\n.gcard.hl{box-shadow:0 0 0 3px var(--accent)}\n\n/* Toutes les tâches : liste compacte */\n.spr{margin-bottom:18px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden}\n.spr.cur{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}\n.sprh{all:unset;box-sizing:border-box;cursor:pointer;width:100%;display:grid;grid-template-columns:auto minmax(0,1fr) minmax(90px,180px) auto;gap:14px;align-items:center;padding:12px 16px;background:var(--sunk)}\n.sprh:hover{background:var(--line)}\n.sprh:focus-visible{outline:3px solid var(--accent);outline-offset:-3px}\n.sprh .sn{font-family:var(--f-display);font-weight:800;font-size:24px;line-height:1}\n.sprh .sd{font-size:14px;color:var(--muted);min-width:0}\n.sprh .sd b{color:var(--fg);font-weight:600}\n.sprh .sm{display:inline-block;font-size:12px;font-weight:700;padding:2px 7px;border-radius:6px;background:var(--accent-soft);color:var(--accent);margin-left:6px}\n.sprh .go{font-size:13px;font-weight:600;color:var(--accent);white-space:nowrap}\n.mbar{height:6px;background:var(--line);border-radius:99px;overflow:hidden;display:flex}\n.mbar i{display:block;height:100%}\n.mnum{font-family:var(--f-mono);font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums;margin-top:3px;text-align:right}\n.glist{display:flex;flex-direction:column}\n.grow{border-top:1px solid var(--line)}\n.grow>button{all:unset;box-sizing:border-box;cursor:pointer;width:100%;display:grid;grid-template-columns:4px minmax(0,1fr) auto 110px 16px;gap:12px;align-items:center;padding:9px 16px 9px 0}\n.grow>button:hover{background:var(--sunk)}\n.grow>button:focus-visible{outline:3px solid var(--accent);outline-offset:-3px}\n.grow .stripe{align-self:stretch;background:var(--c);border-radius:0 3px 3px 0}\n.grow .gt{font-weight:600;font-size:15px;min-width:0;display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.grow .gw{font-size:13px;color:var(--muted);white-space:nowrap}\n.grow .chev{font-size:12px;color:var(--muted);transition:transform .15s}\n.grow.open .chev{transform:rotate(90deg)}\n.grow.alldone .gt>span:first-child{text-decoration:line-through;color:var(--muted)}\n.grow .subs{padding:0 12px 10px 20px}\n.grow .badge{margin-left:0}\n.mini{display:flex;flex-direction:column;gap:3px}\n\n/* Fenêtre sprint */\n.sheet{background:var(--bg);border:1px solid var(--line);border-radius:14px;width:min(1100px,100%);display:flex;flex-direction:column;overflow:hidden;margin-bottom:24px}\n.sheet>header{background:var(--surface);border-bottom:1px solid var(--line);padding:18px 20px;display:flex;flex-direction:column;gap:12px}\n.sheet .sh1{display:flex;gap:12px;align-items:flex-start;flex-wrap:wrap}\n.sheet .sh1 h2{font-size:30px;font-weight:800;line-height:1.1}\n.sheet .sh1 h2 small{font:500 16px var(--f-body);color:var(--muted);margin-left:8px}\n.sheet .sh1 .sp{flex:1}\n.sheet .navb{display:flex;gap:6px}\n.sheet .st{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;padding:3px 9px;border-radius:99px;background:var(--sunk);color:var(--muted)}\n.sheet .st.live{background:var(--accent);color:var(--bg)}\n.sheet .milebox{background:var(--accent-soft);border-radius:var(--r);padding:10px 14px;font-size:15px}\n.sheet .milebox b{color:var(--accent)}\n.sheet .stats{display:flex;gap:18px;flex-wrap:wrap;align-items:center;font-size:14px;color:var(--muted)}\n.sheet .stats .bar{flex:1 1 220px;margin:0;height:10px}\n.sheet .stats b{color:var(--fg);font-variant-numeric:tabular-nums}\n.sheet .sb{padding:18px 20px;display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;align-items:start}\n.sheet .sb .col{gap:8px}\n@media (max-width:700px){\n  .sprh{grid-template-columns:auto minmax(0,1fr)}\n  .sprh .mini,.sprh .go{grid-column:2}\n  .grow>button{grid-template-columns:4px minmax(0,1fr) 16px}\n  .grow .gw,.grow .mini{display:none}\n  .sheet .sh1 h2{font-size:24px}\n  .scrim{padding:8px}\n}\nbutton.chip{font:inherit;font-size:13.5px;width:100%;text-align:left;cursor:pointer}\nbutton.chip:hover{border-color:var(--c)}\n.wk button{all:unset;cursor:pointer;display:block}\n.wk button:hover h3{color:var(--accent)}\n.wk button:focus-visible{outline:3px solid var(--accent);outline-offset:2px;border-radius:6px}\n.wk .see{font-size:12px;font-weight:600;color:var(--accent)}\n.ms.clk{cursor:pointer}\n.ms.clk:hover{border-color:var(--fg)}\n@media (max-width:1000px){.progress{grid-template-columns:repeat(3,minmax(0,1fr))}}\n@media (max-width:700px){\n  .progress,.alerts{grid-template-columns:1fr}\n  .top{grid-template-columns:1fr}\n  .ms{grid-template-columns:1fr}\n  .form .two{grid-template-columns:1fr}\n}\n@media (prefers-reduced-motion:no-preference){.tabs button,.chipbtn,.sub{transition:background .15s,color .15s,border-color .15s}}\na{color:var(--accent)}\n.tlog{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden}\n.lrow{display:grid;grid-template-columns:150px 130px 110px minmax(0,1fr) auto;gap:12px;align-items:start;padding:10px 14px;border-bottom:1px solid var(--line)}\n.lrow:last-child{border-bottom:0}\n.lrow .when{font-size:14px;font-variant-numeric:tabular-nums;color:var(--muted)}\n.lrow .who{display:flex;gap:6px;align-items:center;font-weight:600}\n.lrow .tt{font-weight:600}\n.lrow .tid{font-size:12px;color:var(--muted);font-family:var(--f-mono)}\n.lrow .diff{font-size:14px;color:var(--muted);display:flex;flex-wrap:wrap;gap:4px 12px;margin-top:2px}\n.lrow .diff strong{color:var(--fg)}\n.act{display:inline-block;font-size:12px;font-weight:700;padding:2px 8px;border-radius:99px;background:var(--sunk);color:var(--fg)}\n.a-status{background:var(--done-soft);color:var(--done)} .a-create{background:var(--theo-soft);color:var(--theo)}\n.a-delete{background:var(--blocked-soft);color:var(--blocked)} .a-edit{background:var(--doing-soft);color:var(--doing)}\n.a-revert{background:var(--art-soft);color:var(--art)}\n.small{font-size:13px!important;padding:5px 10px!important}\n.people{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}\n.pcard{background:var(--surface);border:1px solid var(--line);border-top:4px solid var(--c);border-radius:var(--r);padding:14px 16px;display:flex;flex-direction:column;gap:10px}\n.pcard h3{font-size:22px}\n.muted.small{font-size:13px}\n.nums{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.nums div{display:flex;flex-direction:column}\n.nums b{font-family:var(--f-display);font-size:26px;line-height:1.1;font-variant-numeric:tabular-nums}\n.nums span{font-size:12px;color:var(--muted)}\n.urow{display:grid;grid-template-columns:auto minmax(160px,240px) 150px 1fr;gap:12px;align-items:center;padding:12px 14px;border-bottom:1px solid var(--line)}\n.urow:last-child{border-bottom:0}\n.urow .nm{display:flex;flex-direction:column;gap:4px;font-size:12px;font-weight:600;color:var(--muted)}\n.urow input{font:500 15px var(--f-body);padding:7px 10px;border:1.5px solid var(--line);border-radius:8px;background:var(--surface);color:var(--fg)}\n.urow .ub{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}\n.urow .code{grid-column:1/-1;background:var(--doing-soft);border:1px solid var(--doing);border-radius:8px;padding:10px 12px}\n.urow .code .big{font-family:var(--f-mono);font-size:22px;font-weight:700;letter-spacing:.15em}\n@media (max-width:800px){\n  .lrow{grid-template-columns:1fr 1fr}\n  .lrow .what{grid-column:1/-1}\n  .urow{grid-template-columns:auto 1fr}\n  .urow>div{grid-column:2}\n}\n\n.urow select{font:500 14px var(--f-body);padding:6px 8px;border:1.5px solid var(--line);border-radius:8px;background:var(--surface);color:var(--fg)}\n.urow.add{background:var(--sunk)}\n\n.dform .urow{grid-template-columns:auto 1fr}\n.nm.wide{max-width:640px}\n.nm.wide input{width:100%}\n\n.dform .lrowx{grid-template-columns:auto 1fr auto}\n.lfields{display:grid;grid-template-columns:minmax(120px,200px) 1fr;gap:10px}\n.lfields input{width:100%}\n@media (max-width:800px){.dform .lrowx{grid-template-columns:auto 1fr}.lfields{grid-template-columns:1fr}.lrowx>.ub{grid-column:2}}\n</style></head><body><div class=\"wrap\">\n  <div class=\"top\">\n    <div>\n      <h1>Anachro — Admin</h1>\n      <div class=\"sub\">Qui a fait quoi, quand. Annuler une modification, gérer les accès.</div>\n    </div>\n    <div class=\"now\"><div class=\"pill-box\"><div class=\"k\">Navigation</div><div class=\"v\"><small><a href=\"/\">← Retour au planning</a></small></div></div></div>\n  </div>\n\n  <nav class=\"tabs\" role=\"tablist\" aria-label=\"Sections admin\">\n    <button role=\"tab\" data-tab=\"activite\" aria-selected=\"true\">Activité</button>\n    <button role=\"tab\" data-tab=\"personnes\">Par personne</button>\n    <button role=\"tab\" data-tab=\"comptes\">Comptes &amp; codes</button>\n    <button role=\"tab\" data-tab=\"liens\">Liens (GDD…)</button>\n    <button role=\"tab\" data-tab=\"discord\">Discord</button>\n  </nav>\n  <div id=\"dbnote\" class=\"banner\" hidden></div>\n\n  <section data-panel=\"activite\">\n    <div class=\"toolbar\">\n      <select id=\"f-user\" aria-label=\"Personne\"><option value=\"\">Tout le monde</option></select>\n      <select id=\"f-action\" aria-label=\"Type d'action\">\n        <option value=\"\">Toutes les actions</option>\n        <option value=\"status\">Statut changé</option>\n        <option value=\"edit\">Tâche modifiée</option>\n        <option value=\"create\">Tâche ajoutée</option>\n        <option value=\"delete\">Tâche supprimée</option>\n        <option value=\"revert\">Annulation</option>\n        <option value=\"login\">Connexion</option>\n        <option value=\"account\">Compte modifié</option>\n        <option value=\"links\">Liens modifiés</option>\n      </select>\n      <select id=\"f-when\" aria-label=\"Période\">\n        <option value=\"today\">Aujourd'hui</option>\n        <option value=\"7\" selected>7 derniers jours</option>\n        <option value=\"30\">30 derniers jours</option>\n        <option value=\"all\">Tout</option>\n      </select>\n      <button class=\"ghost\" type=\"button\" id=\"refresh\">Actualiser</button>\n    </div>\n    <div class=\"tlog\" id=\"log\"></div>\n    <div style=\"margin-top:12px\"><button class=\"ghost\" type=\"button\" id=\"more\" hidden>Voir plus ancien</button></div>\n  </section>\n\n  <section data-panel=\"personnes\" hidden>\n    <p class=\"note\">Sur les 7 derniers jours. « Cochées » = tâches passées à Fait.</p>\n    <div class=\"people\" id=\"people\"></div>\n  </section>\n\n  <section data-panel=\"liens\" hidden>\n    <p class=\"note\">Ces liens s'affichent en boutons en haut du planning, pour tout le monde (spectateurs compris). GDD, PDF, Google Doc, Figma, Drive… n'importe quelle adresse <code>https://</code>. Pour un PDF : mets-le sur Google Drive (partage « Tous les utilisateurs disposant du lien ») et colle le lien ici.</p>\n    <form class=\"tlist dform\" id=\"lform\">\n      <div id=\"l-rows\"></div>\n      <div class=\"urow\"><span></span><div class=\"ub\" style=\"grid-column:2/-1;justify-content:flex-start\">\n        <button class=\"ghost small\" type=\"button\" id=\"l-add\">+ Ajouter un lien</button>\n        <button class=\"primary small\" type=\"submit\">Enregistrer</button>\n      </div></div>\n    </form>\n  </section>\n\n  <section data-panel=\"discord\" hidden>\n    <p class=\"note\">Le bot poste dans un salon Discord : récap le lundi à 8h45 et bilan le vendredi à 16h30 (semaines studio), alertes J-3 / J-1 avant les jalons, et alerte immédiate quand une tâche passe en « Bloqué ».</p>\n    <form class=\"tlist dform\" id=\"dform\">\n      <div class=\"urow\"><span></span><label class=\"nm wide\">Webhook du salon #planning<input id=\"d-url\" placeholder=\"https://discord.com/api/webhooks/…\" autocomplete=\"off\"></label></div>\n      <div id=\"d-ids\"></div>\n      <div class=\"urow\"><span></span><div class=\"ub\" style=\"grid-column:2/-1;justify-content:flex-start\">\n        <button class=\"primary small\" type=\"submit\">Enregistrer</button>\n        <button class=\"ghost small\" type=\"button\" data-job=\"test\">Envoyer un test</button>\n        <button class=\"ghost small\" type=\"button\" data-job=\"recap\">Envoyer le récap maintenant</button>\n        <button class=\"ghost small\" type=\"button\" data-job=\"review\">Envoyer le bilan maintenant</button>\n      </div></div>\n    </form>\n    <p class=\"note\" style=\"margin-top:12px\">Identifiant Discord : dans Discord, Paramètres → Avancés → active le Mode développeur, puis clic droit sur la personne → « Copier l'identifiant de l'utilisateur ». Sans identifiant, le prénom est écrit sans mention.</p>\n  </section>\n\n  <section data-panel=\"comptes\" hidden>\n    <p class=\"note\">Chaque personne se connecte avec son nom + son code. Génère un code et envoie-le-lui en privé : il ne sera plus affiché ensuite.</p>\n    <div class=\"tlist\" id=\"users\"></div>\n  </section>\n</div>\n<script>const $ = (s,r=document) => r.querySelector(s);\nconst el = (tag, cls, html) => { const e=document.createElement(tag); if(cls) e.className=cls; if(html!=null) e.innerHTML=html; return e; };\nconst esc = s => String(s??\"\").replace(/[&<>\"]/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c]));\nconst ST = {todo:\"À faire\", doing:\"En cours\", done:\"Fait\", blocked:\"Bloqué\"};\nconst ACT = {status:\"Statut\", edit:\"Modifiée\", create:\"Ajoutée\", delete:\"Supprimée\", revert:\"Annulation\", login:\"Connexion\", account:\"Compte\", import:\"Import\", links:\"Liens\"};\nconst FIELDS = {t:\"titre\", gt:\"groupe\", who:\"personne\", wk:\"semaine\", cat:\"catégorie\", s:\"statut\"};\nconst COLOR = id => !id ? \"tous\" : id.startsWith(\"art\") ? \"art\" : ([\"theo\",\"celian\",\"olivier\"].includes(id) ? id : \"tous\");\nlet people = {}, tasks = {}, lastId = 0;\n\nfunction note(m){ const n=$(\"#dbnote\"); n.textContent=m; n.hidden=false; }\nasync function api(path, opts={}){\n  const r = await fetch(path,{credentials:\"same-origin\",headers:{\"content-type\":\"application/json\"},...opts});\n  let j={}; try{ j=await r.json(); }catch(e){}\n  if(r.status===401){ document.body.innerHTML = `<div class=\"wrap\"><div class=\"empty\">Connecte-toi d'abord sur <a href=\"/\">la page du planning</a>, puis reviens ici.</div></div>`; throw new Error(\"auth\"); }\n  if(r.status===403){ document.body.innerHTML = `<div class=\"wrap\"><div class=\"empty\">Cette page est réservée à l'admin. <a href=\"/\">Retour au planning</a></div></div>`; throw new Error(\"forbidden\"); }\n  if(!r.ok) throw new Error(j.error||(\"Erreur \"+r.status));\n  return j;\n}\nconst name = id => id ? (people[id] || id) : \"Système\";\nconst fmt = ts => new Date(ts).toLocaleString(\"fr-FR\",{weekday:\"short\",day:\"2-digit\",month:\"2-digit\",hour:\"2-digit\",minute:\"2-digit\"});\nconst val = (k,v) => k===\"s\" ? (ST[v]||v) : k===\"who\" ? name(v) : (v ?? \"—\");\n\nfunction diff(row){\n  const b = row.before ? JSON.parse(row.before) : null, a = row.after ? JSON.parse(row.after) : null;\n  if(row.action===\"account\" && a) return a.created ? `Compte créé : ${esc(name(a.account))} (${a.role===\"viewer\"?\"spectateur\":\"membre\"})` : `Compte ${esc(name(a.account))} : ${[a.name&&\"nom changé\",a.pin&&\"code changé\",a.role&&(\"rôle → \"+(a.role===\"viewer\"?\"spectateur\":\"membre\"))].filter(Boolean).join(\", \")}`;\n  if(row.action===\"import\" && a) return `${a.count} tâches importées`;\n  if(row.action===\"links\" && a) return a.length ? \"Liens : \"+a.map(l=>`<strong>${esc(l.label)}</strong>`).join(\", \") : \"Tous les liens supprimés\";\n  if(row.action===\"login\") return \"\";\n  if(!b && a) return `Créée : ${esc(a.gt)} · ${esc(val(\"who\",a.who))} · ${esc(a.wk)}`;\n  if(b && !a) return `Supprimée (était : ${esc(b.gt)} · ${esc(val(\"who\",b.who))} · ${esc(b.wk)})`;\n  if(!b || !a) return \"\";\n  return Object.keys(FIELDS).filter(k=>b[k]!==a[k]).map(k=>`<span class=\"ch\"><b>${FIELDS[k]}</b> ${esc(val(k,b[k]))} → <strong>${esc(val(k,a[k]))}</strong></span>`).join(\"\");\n}\nfunction taskTitle(row){\n  const t = row.after ? JSON.parse(row.after) : row.before ? JSON.parse(row.before) : null;\n  if(!t || !t.t) return \"\";\n  return `<div class=\"tt\">${esc(t.t)}</div><div class=\"tid\">${esc(t.gt||\"\")} · ${esc(row.task_id)}</div>`;\n}\n\nfunction filters(){\n  const q = new URLSearchParams(); const u=$(\"#f-user\").value, a=$(\"#f-action\").value, w=$(\"#f-when\").value;\n  if(u) q.set(\"user\",u); if(a) q.set(\"action\",a);\n  if(w===\"today\"){ const d=new Date(); d.setHours(0,0,0,0); q.set(\"from\",d.getTime()); }\n  else if(w!==\"all\") q.set(\"from\", Date.now()-Number(w)*864e5);\n  q.set(\"limit\",\"150\"); return q;\n}\nasync function loadLog(append=false){\n  const q = filters(); if(append && lastId) q.set(\"before\", lastId);\n  const j = await api(\"/api/log?\"+q);\n  const box = $(\"#log\"); if(!append) box.innerHTML=\"\";\n  if(!j.log.length && !append){ box.append(el(\"div\",\"empty\",\"Aucune activité sur cette période.\")); $(\"#more\").hidden=true; return; }\n  for(const row of j.log){\n    const r = el(\"div\",\"lrow c-\"+COLOR(row.user));\n    const canUndo = row.task_id && [\"create\",\"edit\",\"status\",\"delete\",\"revert\"].includes(row.action);\n    r.innerHTML = `<div class=\"when\">${fmt(row.ts)}</div>\n      <div class=\"who\"><i class=\"dot\" style=\"background:var(--c)\"></i>${esc(name(row.user))}</div>\n      <div><span class=\"act a-${row.action}\">${ACT[row.action]||esc(row.action)}</span></div>\n      <div class=\"what\">${taskTitle(row)}<div class=\"diff\">${diff(row)}</div></div>\n      <div class=\"undo\"></div>`;\n    if(canUndo){\n      const b = el(\"button\",\"ghost small\",\"Annuler\"); b.type=\"button\"; b.title=\"Remettre la tâche dans l'état d'avant cette action\";\n      b.addEventListener(\"click\",async()=>{\n        if(b.dataset.armed!==\"1\"){ b.dataset.armed=\"1\"; b.textContent=\"Confirmer\"; return; }\n        try{ await api(`/api/log/${row.id}/revert`,{method:\"POST\"}); loadLog(); }catch(e){ note(\"Annulation impossible : \"+e.message); }\n      });\n      $(\".undo\",r).append(b);\n    }\n    box.append(r);\n  }\n  lastId = j.log[j.log.length-1].id;\n  $(\"#more\").hidden = j.log.length < 150;\n}\n\nasync function loadPeople(){\n  const since = Date.now()-7*864e5;\n  const [s, u] = await Promise.all([api(\"/api/stats?since=\"+since), api(\"/api/users\")]);\n  const last = Object.fromEntries(u.last.map(x=>[x.user,x.last]));\n  const box = $(\"#people\"); box.innerHTML=\"\";\n  const doneLog = await api(\"/api/log?action=status&limit=500&from=\"+since);\n  for(const p of u.users){\n    const acts = s.activity.filter(a=>a.user===p.id);\n    const total = acts.filter(a=>a.action!==\"login\").reduce((n,a)=>n+a.n,0);\n    const checked = doneLog.log.filter(r=>r.user===p.id && r.after && JSON.parse(r.after).s===\"done\").length;\n    const mine = s.tasks.filter(t=>t.who===p.id); const all = mine.reduce((n,t)=>n+t.n,0); const done = mine.filter(t=>t.s===\"done\").reduce((n,t)=>n+t.n,0);\n    const c = el(\"div\",\"pcard c-\"+COLOR(p.id));\n    c.innerHTML = `<h3>${esc(p.name)}</h3><div class=\"muted small\">${p.role===\"admin\"?\"Admin · \":\"\"}${last[p.id]?\"Dernière activité : \"+fmt(last[p.id]):\"Aucune activité\"}</div>\n      <div class=\"nums\"><div><b>${checked}</b><span>cochées (7 j)</span></div><div><b>${total}</b><span>modifs (7 j)</span></div><div><b>${all?Math.round(100*done/all):0} %</b><span>de ses tâches faites</span></div></div>`;\n    const b = el(\"button\",\"ghost small\",\"Voir son activité\"); b.type=\"button\";\n    b.addEventListener(\"click\",()=>{ $(\"#f-user\").value=p.id; $(\"#f-when\").value=\"7\"; show(\"activite\"); loadLog(); });\n    c.append(b); box.append(c);\n  }\n}\n\nfunction genCode(){ const a = crypto.getRandomValues(new Uint32Array(1))[0] % 1000000; return String(a).padStart(6,\"0\"); }\nasync function loadUsers(){\n  const u = await api(\"/api/users\");\n  const box = $(\"#users\"); box.innerHTML=\"\";\n  const add = el(\"form\",\"urow add\");\n  add.innerHTML = `<i class=\"dot\" style=\"background:var(--tous)\"></i>\n    <label class=\"nm\">Nouveau compte<input id=\"new-name\" maxlength=\"40\" placeholder=\"Prénom (ex : un prof)\"></label>\n    <label class=\"nm\">Rôle<select id=\"new-role\"><option value=\"viewer\">Spectateur (lecture seule)</option><option value=\"member\">Membre (peut modifier)</option></select></label>\n    <div class=\"ub\"><button class=\"primary small\" type=\"submit\">Ajouter le compte</button></div>`;\n  add.addEventListener(\"submit\",async e=>{ e.preventDefault();\n    try{ await api(\"/api/users\",{method:\"POST\",body:JSON.stringify({name:$(\"#new-name\").value, role:$(\"#new-role\").value})}); await init(); await loadUsers(); note(\"Compte ajouté. Crée-lui un code pour qu'il puisse se connecter.\"); }catch(x){ note(x.message); } });\n  box.append(add);\n  for(const p of u.users){\n    const r = el(\"div\",\"urow c-\"+COLOR(p.id));\n    const state = p.lock_until > Date.now() ? `<span class=\"act a-delete\">Bloqué (trop d'essais)</span>` : p.has_pin ? `<span class=\"act a-create\">A un code</span>` : `<span class=\"act a-login\">Pas encore de code</span>`;\n    r.innerHTML = `<i class=\"dot\" style=\"background:var(--c)\"></i>\n      <label class=\"nm\">Nom<input id=\"nm-${p.id}\" value=\"${esc(p.name)}\" maxlength=\"40\"></label>\n      <div class=\"rl\">${p.role===\"admin\"?\"<b>Admin</b>\":`<select id=\"rl-${p.id}\" aria-label=\"Rôle de ${esc(p.name)}\"><option value=\"member\">Membre</option><option value=\"viewer\">Spectateur</option></select>`}<br>${state}</div>\n      <div class=\"ub\"></div><div class=\"code\" id=\"code-${p.id}\" hidden></div>`;\n    const save = el(\"button\",\"ghost small\",\"Enregistrer le nom\"); save.type=\"button\";\n    save.addEventListener(\"click\",async()=>{ try{ await api(\"/api/users/\"+p.id,{method:\"POST\",body:JSON.stringify({name:$(\"#nm-\"+p.id).value})}); await init(); note(\"Nom enregistré.\"); }catch(e){ note(e.message); } });\n    const code = el(\"button\",\"primary small\", p.has_pin?\"Nouveau code\":\"Créer un code\"); code.type=\"button\";\n    code.addEventListener(\"click\",async()=>{\n      if(p.role===\"admin\" && code.dataset.armed!==\"1\"){ code.dataset.armed=\"1\"; code.textContent=\"Sûr ? (ton propre code)\"; return; }\n      const c = genCode();\n      try{ await api(\"/api/users/\"+p.id,{method:\"POST\",body:JSON.stringify({pin:c})});\n        const box = $(\"#code-\"+p.id); box.hidden=false; box.innerHTML=`Code de <b>${esc(p.name)}</b> : <span class=\"big\">${c}</span> — envoie-le-lui en privé, il ne sera plus affiché.`;\n      }catch(e){ note(e.message); }\n    });\n    $(\".ub\",r).append(save, code); box.append(r);\n    const rs = $(\"#rl-\"+p.id);\n    if(rs){ rs.value = p.role; rs.addEventListener(\"change\",async()=>{ try{ await api(\"/api/users/\"+p.id,{method:\"POST\",body:JSON.stringify({role:rs.value})}); note(`${p.name} est maintenant ${rs.value===\"viewer\"?\"spectateur (lecture seule)\":\"membre\"}.`); }catch(e){ note(e.message); rs.value=p.role; } }); }\n  }\n}\n\nasync function loadDiscord(){\n  const [cfg, u] = await Promise.all([api(\"/api/discord\"), api(\"/api/users\")]);\n  $(\"#d-url\").value = cfg.planning || \"\";\n  const box = $(\"#d-ids\"); box.innerHTML = \"\";\n  for(const p of u.users.filter(x=>x.role!==\"viewer\")){\n    const r = el(\"div\",\"urow c-\"+COLOR(p.id));\n    r.innerHTML = `<i class=\"dot\" style=\"background:var(--c)\"></i><label class=\"nm wide\">Identifiant Discord de ${esc(p.name)}<input data-uid=\"${esc(p.id)}\" value=\"${esc((cfg.ids||{})[p.id]||\"\")}\" inputmode=\"numeric\" placeholder=\"ex : 123456789012345678\"></label>`;\n    box.append(r);\n  }\n}\n$(\"#dform\").addEventListener(\"submit\",async e=>{ e.preventDefault();\n  const ids = {}; document.querySelectorAll(\"#d-ids input\").forEach(i=>ids[i.dataset.uid]=i.value.trim());\n  try{ await api(\"/api/discord\",{method:\"POST\",body:JSON.stringify({planning:$(\"#d-url\").value.trim(), ids})}); note(\"Réglages Discord enregistrés.\"); }catch(x){ note(x.message); } });\ndocument.querySelectorAll(\"#dform [data-job]\").forEach(b=>b.addEventListener(\"click\",async()=>{\n  try{ await api(\"/api/discord/test\",{method:\"POST\",body:JSON.stringify({job:b.dataset.job})}); note(\"Message envoyé dans Discord.\"); }catch(x){ note(x.message); } }));\n\nfunction linkRow(l={label:\"\",url:\"\"}){\n  const r = el(\"div\",\"urow lrowx\");\n  r.innerHTML = `<span class=\"lgrip\" aria-hidden=\"true\">🔗</span><div class=\"lfields\"><label class=\"nm\">Nom du bouton<input class=\"l-label\" maxlength=\"40\" placeholder=\"ex : GDD\" value=\"${esc(l.label)}\"></label><label class=\"nm\">Adresse<input class=\"l-url\" placeholder=\"https://…\" value=\"${esc(l.url)}\" autocomplete=\"off\"></label></div><div class=\"ub\"><button class=\"ghost small\" type=\"button\" data-mv=\"-1\" aria-label=\"Monter\">↑</button><button class=\"ghost small\" type=\"button\" data-mv=\"1\" aria-label=\"Descendre\">↓</button><button class=\"danger small\" type=\"button\" data-rm aria-label=\"Supprimer ce lien\">Supprimer</button></div>`;\n  r.querySelector(\"[data-rm]\").addEventListener(\"click\",()=>r.remove());\n  r.querySelectorAll(\"[data-mv]\").forEach(b=>b.addEventListener(\"click\",()=>{ const box=$(\"#l-rows\"); if(b.dataset.mv===\"-1\"&&r.previousElementSibling) box.insertBefore(r,r.previousElementSibling); if(b.dataset.mv===\"1\"&&r.nextElementSibling) box.insertBefore(r.nextElementSibling,r); }));\n  return r;\n}\nasync function loadLinks(){\n  const j = await api(\"/api/links\");\n  const box = $(\"#l-rows\"); box.innerHTML=\"\";\n  (j.links.length ? j.links : [{label:\"GDD\",url:\"\"}]).forEach(l=>box.append(linkRow(l)));\n}\n$(\"#l-add\").addEventListener(\"click\",()=>{ if($(\"#l-rows\").children.length>=8) return note(\"8 liens maximum.\"); const r=linkRow(); $(\"#l-rows\").append(r); r.querySelector(\"input\").focus(); });\n$(\"#lform\").addEventListener(\"submit\",async e=>{ e.preventDefault();\n  const links=[...document.querySelectorAll(\"#l-rows .urow\")].map(r=>({label:r.querySelector(\".l-label\").value.trim(), url:r.querySelector(\".l-url\").value.trim()}));\n  try{ await api(\"/api/links\",{method:\"POST\",body:JSON.stringify({links})}); note(\"Liens enregistrés : ils apparaissent en haut du planning.\"); loadLinks(); }catch(x){ note(x.message); } });\n\nconst TABS=[\"activite\",\"personnes\",\"comptes\",\"liens\",\"discord\"];\nfunction show(t){\n  document.querySelectorAll(\".tabs button\").forEach(b=>b.setAttribute(\"aria-selected\",String(b.dataset.tab===t)));\n  document.querySelectorAll(\"[data-panel]\").forEach(s=>s.hidden=s.dataset.panel!==t);\n  if(t===\"activite\") loadLog().catch(e=>note(e.message));\n  if(t===\"personnes\") loadPeople().catch(e=>note(e.message));\n  if(t===\"comptes\") loadUsers().catch(e=>note(e.message));\n  if(t===\"discord\") loadDiscord().catch(e=>note(e.message));\n  if(t===\"liens\") loadLinks().catch(e=>note(e.message));\n}\ndocument.querySelectorAll(\".tabs button\").forEach(b=>b.addEventListener(\"click\",()=>show(b.dataset.tab)));\n[\"#f-user\",\"#f-action\",\"#f-when\"].forEach(s=>$(s).addEventListener(\"change\",()=>loadLog().catch(e=>note(e.message))));\n$(\"#refresh\").addEventListener(\"click\",()=>loadLog().catch(e=>note(e.message)));\n$(\"#more\").addEventListener(\"click\",()=>loadLog(true).catch(e=>note(e.message)));\n\nasync function init(){\n  const st = await (await fetch(\"/api/state\")).json();\n  people = Object.fromEntries(st.people.map(p=>[p.id,p.name]));\n  const sel = $(\"#f-user\"); const cur = sel.value; sel.innerHTML = `<option value=\"\">Tout le monde</option>`;\n  st.people.forEach(p=>{ const o=el(\"option\",null,esc(p.name)); o.value=p.id; sel.append(o); }); sel.value=cur;\n}\ninit().then(()=>loadLog()).catch(e=>{ if(![\"auth\",\"forbidden\"].includes(e.message)) note(e.message); });\nsetInterval(()=>{ if(!document.hidden && !$(\"[data-panel=activite]\").hidden && !lastIdLocked()) loadLog().catch(()=>{}); }, 20000);\nfunction lastIdLocked(){ return !$(\"#more\").hidden && $(\"#log\").children.length>150; }\n\n{ const h=location.hash.slice(1); if(TABS.includes(h)) show(h); }\n</script></body></html>";
